export const NL_TEXTS: Record<string, string> = {
  "t.100yncnvyr7": "Filters op roepnaam, prefix en al gewerkt",
  "t.104ebzp7fgn": "Uitgang: de kaart die audio naar de radio stuurt om te zenden (meestal “Speakers (USB Audio Device)”).",
  "t.105xxpznogh": "SSTV: luisteren blijft aan en handiger log",
  "t.10arsvkq0ry": "Contest: TX blijft aan",
  "t.10h6betrvbn": "Log4OM logt de QSO’s van Aurora zoals die van JTDX. De radio wordt apart gekoppeld (onderdeel “Log4OM: de radio via Aurora”).",
  "t.10j33wt9l45": "In Instellingen › Kleuren, in de groep DX-kaart, kun je de kleuren van «Gewerkt vierkant» en «Bevestigd vierkant» kiezen (verzoek #40). Ze gelden ook voor de legenda en de wereldkaart, en «Kleuren herstellen» zet ze terug op geel en groen.",
  "t.10jxym9lci5": "In Log4OM: Settings → Program configuration → CAT interface. CAT Engine: Hamlib.",
  "t.10m903hhe8o": "Geen CQ? Aurora meldt het in een aparte melding: standaard beantwoordt het alleen CQ’s. Om elk bericht te beantwoorden: [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]].",
  "t.10pklmh7q3z": "In PSK komt elk bit met zijn waarschijnlijkheid en de varicode wordt als hele woorden gelezen: een twijfelachtig bit breekt het teken niet en ruis drukt heel weinig af (onder een bepaalde waarschijnlijkheid wordt het teken niet afgedrukt). In het ontvangstvenster zet een dubbelklik op een roepnaam die in de lopende QSO en zoekt naam, QTH, locator en land op; rechtsklikken op een woord zet het in het gekozen logveld, en “[[digi.word.copy]]” en “[[digi.mi.clearRx]]” zijn er altijd.",
  "t.10ufnvi1wp": "Om een UltraFOX- of SuperFox-expeditie te roepen: schakel Hound in FT8 in. Aurora decodeert ook het brede signaal en antwoordt zoals bij klassieke Fox.",
  "t.114rqzxlcu9": "SSTV: FSK-ID en mode wordt vanzelf herkend",
  "t.1186eqb7vcp": "Hounds roepen boven 1000 Hz, nooit eronder: het lage deel is van de Fox.",
  "t.119yfnb60dq": "Fox en Hound: wat ze zijn",
  "t.11fgtosqin8": "Test: maak een QSO; de regel verschijnt in het Log4OM-logboek.",
  "t.11p7xdncsdq": "Multimode Aurora: JT65 B/C voor EME, MSK144 op 30 s en «Sh», decodeeropties van WSJT-X",
  "t.11pm9ffshzw": "Verkenner opent met het bestand Aurora-assistenza-….zip al geselecteerd: stuur het per e-mail, WhatsApp of Telegram.",
  "t.11rm4otni1b": "Veelvoorkomende problemen",
  "t.120m8bxhfou": "Een telefoon of tablet koppelen",
  "t.124dev7bxmf": "[[nav.log]]",
  "t.127aqvg013u": "Weet je poort en snelheid niet? Probeer “[[cat.detect]]”: het vindt ze voor je. Als je OmniRig gebruikte, staan ze in het instellingenvenster daarvan.",
  "t.12t4vf11p7a": "Naast de bandknoppen staat een lijst met alle frequenties van de huidige modus, gegroepeerd per band: de standaard en de alternatieven (ook die van DXpedities); de hoofdfrequentie van elke band heeft een gekleurde stip. Kies er een en Aurora stemt de radio daarop af. Bewerk de lijst in Instellingen › Modi › Gemeenschappelijk voor alle modi › Frequenties.",
  "t.12ym175c24d": "Open het log: na ongeveer 15 seconden, de tijd die het nodig heeft om op te starten, komen de QSO’s vanzelf aan in de volgorde waarin je ze maakte.",
  "t.130ehgvk7vl": "Er komt niets aan: een ander programma gebruikt poort 2237 al (GridTracker, JTAlert, een ander logprogramma). Gebruik een andere vrije poort (bijvoorbeeld 2239), zowel in Aurora als in LogHX.",
  "t.134f56zi51": "In Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[int.title]]” › “+ [[int.p.loghx]]”. Laat 127.0.0.1, poort 2237, “[[int.wsjtx]]” en “[[int.loggedAdif]]” aan.",
  "t.135v7u6ma2a": "Op de telefoon staat de knop [[stop.button]] onderaan het scherm.",
  "t.13hkzy551no": "Stem af op een SSTV-frequentie (bijvoorbeeld 14,230 MHz USB) en open [[nav.sstv]]: het luisteren begint vanzelf en blijft aan tot je op “[[sstv.rx.stop]]” drukt, ook terwijl je een beeld voorbereidt in “[[sstv.view.tx]]”. De modus wordt herkend aan de VIS of, als de VIS gemist is, aan het ritme van de synchronisatielijnen; eenmaal herkend blijft hij tot het einde van het beeld.",
  "t.13mr7c3vmbl": "Open [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]].",
  "t.142aloo356f": "Aurora kan wachten tot de DX vrij is in plaats van over hem heen te zenden.",
  "t.142h4cihhyg": "Modus Q65",
  "t.144pyc9l29m": "Een CQ beantwoorden",
  "t.147zpak6kbr": "CW ontvangen en zenden",
  "t.14g5iqm4hu6": "Log4OM: de radio via Aurora",
  "t.14gexx04zz1": "DX-split vanuit de DX Cluster",
  "t.14wu3ep0mo5": "Dit zijn de meldingen die enkele seconden blijven staan (bijv. “Antwoorden …”). Ze verschijnen direct bij de klik; mislukt het commando daarna, dan worden ze een fout.",
  "t.156d0m7co0l": "Onbevestigde landen",
  "t.158x1rit5ou": "Het gelogde QSO heeft ook een eigen geluid: “[[snd.ev.qso_logged]]” (standaard de fanfare). Je kunt een ander geluid kiezen, de stem, een eigen WAV/MP3-bestand of geen geluid.",
  "t.15ezj5mfb7": "Gaat niet in TX: dan is het CAT (poort, snelheid, PTT, CI-V/CAT-menu).",
  "t.15lsvtn93xb": "Aan het begin van de zending verschijnt ook een rode waarschuwing. Breng Tx terug binnen het bereik, of verschuif de frequentie van de radio.",
  "t.15lvekyffkj": "In Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[int.title]]” › “+ [[int.p.bblogger]]”. Laat 127.0.0.1, poort 2237, “[[int.wsjtx]]” en “[[int.loggedAdif]]” aan.",
  "t.15o50f2d9j6": "Oplossingen: FT8-locatorcontrole, OmniRig, Hamlib split, PSK Reporter, audio, watchdog en Wavelog",
  "t.15tagb0nofa": "De geluidskaart",
  "t.164hg10igd5": "Dubbelklikken antwoordt alleen als “[[gen.dblReply]]” aan staat in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]]. Als [[ctl.enable_tx]] niet aangaat, verschijnt er een fout.",
  "t.16c7ljyklpf": "LogHX: QSO’s en “Active calls” via het netwerk (UDP)",
  "t.16ggvygxen4": "Doorgestreepte rij: station al gewerkt.",
  "t.16lit8smebg": "Geldt voor “[[int.adif]]” en “[[int.n1mm]]”, niet voor de WSJT-X-stroom (GridTracker, JTAlert), die tijdens het werken nodig is.",
  "t.16n541rmuta": "Klik op de modusnaam in de onderste balk (of op RTTY in het menu Modus): „[[digi.rtty.title]]” bundelt Rev, AFC, Snap, Squelch, UOS, drempel, frequenties, ontvanger, shift, snelheid en [[digi.rtty.charset]] (ook Cyrillisch en Scandinavisch), in vier profielen Set 1-4 die je met de bolletjes kiest.",
  "t.16n8howvnoh": "Ik zie signalen maar niets wordt gedecodeerd",
  "t.16rrzf0bot0": "Test: maak een QSO met Aurora (of voeg er met de hand een toe vanaf de Logboek-pagina): het moet in het LogHX-logboek verschijnen.",
  "t.16v1x8lxse0": "Een tilde voor de waarde (~S3) betekent een schatting op basis van de audio: de radio stuurt de S-meter niet door (bijv. met OmniRig).",
  "t.16x0qf2ouwj": "Elke installatie of update schrijft een logboek in de gegevensmap, handig om te begrijpen wat er misging. Mislukt de installatie, dan stuurt het installatieprogramma bij ingeschakelde rapporten een anoniem rapport; lukt ze met waarschuwingen, dan stuurt Aurora het bij de eerste start. Het installatieprogramma blijft niet meer hangen met wachten op PowerShell.",
  "t.173up6aw9jd": "Als expeditie: vink in [[nav.fox]] “UltraFOX” aan. Elke even periode draagt één signaal van 750 tot 2260 Hz alle stations in de wachtrij (RR73 en rapporten), of de CQ.",
  "t.176jlgscc71": "Tx en Rx: de audiofrequenties in Hz. Typ en druk op Enter; ▲ kopieert Rx naar Tx, ▼ Tx naar Rx.",
  "t.178wpoe9jh1": "Tussen twee naburige vensters zit een scheiding (paarse balk): sleep die om het ene smaller en het andere breder te maken.",
  "t.17e66ly4206": "“[[bands.title]]” toont de propagatie overdag en ’s nachts per bandgroep (de band waarop je zit is gemarkeerd) en de drie verst gelegen stations die jou hebben gehoord. Het vereist de online diensten: schakel in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] propagatie en PSK Reporter in; ontvangstrapporten komen in realtime binnen en de pagina wordt elke 10 seconden vernieuwd.",
  "t.17idfzrpoa6": "Verbind voor Doppler de radio via Hamlib ([[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]), kies de “[[sat.ctl.transponder]]” en schakel “[[sat.ctl.doppler]]” in: boven de minimale elevatie zet Aurora de ontvangst op de hoofd-VFO en het zenden op de split-VFO, elke seconde gecorrigeerd. Verstel bij een lineaire transponder “[[sat.ctl.downlink]]”: de uplink volgt vanzelf, ook als de transponder inverterend is zoals RS-44.",
  "t.17irb1c52xs": "Het werkt niet tijdens het zenden, alleen vanaf de pc waarop Aurora draait en niet met OmniRig. Waarden die de radio weigert, worden overgeslagen. Houd de muis boven een knop om te zien wat de klik doet.",
  "t.17ngl9tvu5d": "Om te zenden schakel je naar “[[sstv.view.tx]]”, kies je de “[[sstv.tx.mode]]” (resolutie en duur staan naast de naam) en laad je een foto met “[[sstv.bg.load]]”, door hem erop te slepen of te plakken met Ctrl+V; kader hem in door te slepen en met het wieltje.",
  "t.17w37jqxgul": "FT8 verwerpt zwakke antwoorden met je eigen roepnaam of die van de DX niet meer, zoals WSJT-X doet. OmniRig heropent niet meer bij elke uitlezing met de radio uit en geeft de poort vrij als CAT wordt verbroken; met Hamlib wordt na opnieuw verbinden de echte split hersteld. PSK Reporter laat geen rapporten ouder dan 3 uur meer op de kaart staan, een geluidskaart die niet opent is weer een waarschuwing, de watchdog meldt een venster dat nooit reageert en Wavelog waarschuwt niet meer voor http:// in thuisnetwerken.",
  "t.188j3esup0v": "Tekst te klein? Kies in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.appearance]] “[[ap.size]]” (tot 160%), of druk op Ctrl + en Ctrl − op elke pagina; Ctrl 0 gaat terug naar 100%.",
  "t.18anw1chi37": "Het uploaden staat standaard uit, zoals “Upload spots” in WSJT-X: uit wordt er niets verzonden. De spots worden openbaar op wsprnet.org; wat er verzonden wordt, staat in de privacyverklaring.",
  "t.18o73rsn9tr": "Open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]].",
  "t.18polm8cyd0": "Een station beantwoorden met een dubbelklik.",
  "t.18rh5v425l9": "De filters verbergen of markeren rijen in de lijsten zonder het decoderen te raken. Ze worden vanzelf opgeslagen.",
  "t.18sudvbonvt": "OmniRig via COM, native Cat4OM, split met OmniRig en TCI, instelbare Tx-vertraging",
  "t.18ua7lh41m": "Oplossingen: Linux, ALSA, TCI, «Clear» voor GridTracker en JTAlert, Wavelog, PSK Reporter",
  "t.18wjuebginy": "Tijdens de contest worden decodes op waarde gesorteerd: punten en nieuwe multipliers bovenaan (★ = aanbevolen), dupes doorgestreept, in geel die niet in de contest zitten. Dubbelklik om te roepen, of “[[contest.cq]]”.",
  "t.191oofqdltx": "Radio’s die werken: SDR’s met TCI die de I/Q-stream sturen, bijv. SunSDR2 (Pro, DX, QS) en ColibriNANO met ExpertSDR2/3, ANAN en Hermes-Lite 2 met Thetis. Of een opgenomen I/Q-WAV-bestand. Radio’s met alleen audio-uitgang volstaan niet.",
  "t.192m67s99ie": "Filteren wie je CQ beantwoordt",
  "t.196dmhw6fxh": "De radio gaat naar TX maar er komt geen vermogen uit: de audio naar de radio ontbreekt.",
  "t.19h3d8rm5vz": "[[nav.propagation]]",
  "t.19kz0hx34ex": "Typ het model in het zoekveld (bijv. FT-2000) en klik erop in de lijst die verschijnt.",
  "t.19phv7jw6sm": "Online logboekdiensten en roepnaamopzoeking",
  "t.19s9elbzpis": "De waterval is zo breed als het radiofilter dat via CAT wordt gelezen (tot 5000 Hz; 0-3000 Hz als de radio het niet meldt). Een groene lijn markeert het begin van elke periode.",
  "t.1a14040cctv": "Kies welke soorten getoond worden (fouten worden altijd getoond) en hoeveel seconden ze blijven.",
  "t.1a8gpdkrntn": "Modi JT65 en JT9",
  "t.1a9f0rbdynx": "Open [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]].",
  "t.1ad0czydufh": "Een zeldzame DXpeditie krijgt honderden oproepen. Om er veel te werken gebruikt de expeditie (de “Fox”) een speciale FT8-modus en volgen de stations die haar roepen (de “Hounds”) nauwkeurige regels.",
  "t.1ahv1wz6y6l": "Klik in de lijst op een satelliet om hem te volgen; het vinkje toont hem op de kaart met zijn radiovoetafdruk. De tabel “[[sat.pass.title]]” geeft begin, maximale elevatie, einde en azimut van de volgende overkomsten.",
  "t.1akvfqmvh5y": "Aurora decodeert met alle processoren op één na. Aanbevolen: 4 kernen en 8 GB geheugen. Met 2 kernen of 4 GB werkt het, maar bij veel signalen kan het decoderen te laat klaar zijn.",
  "t.1aohw3tch91": "Als het koppelen is ingetrokken, doe “[[acc.pair]]” opnieuw vanaf de pc.",
  "t.1aon0lpu0tq": "Elk spoor is een station. De groene balk is jouw ontvangstfrequentie (Rx), de rode jouw zendfrequentie (Tx): ze zijn zo breed als een signaal van de modus (43,75 Hz in FT8).",
  "t.1aq98netqx4": "In PSK31 en PSK63 leest het paneel “[[digi.band.title]]” boven de waterval alle signalen van de gekozen modus tegelijk, elk met een eigen ontvanger (zoals een browser): een signaal komt in de lijst zodra de ontvanger het als PSK herkent, met frequentie, S/R, roepnaam met vlag en laatste tekst (onzekere tekens in grijs). Stations die CQ roepen hebben een gemarkeerde regel en worden bovenaan geteld. Klik om er een te beluisteren, dubbelklik voor de laatste 60 seconden; “[[digi.band.miPsk]]” in het menu Opties zet het uit.",
  "t.1au648yljtx": "Niets gelogd: de verbinding in Log4OM moet actief zijn en op dezelfde poort als Aurora; druk na een wijziging op “Save and apply”.",
  "t.1axtagd9aw6": "aurora.local antwoordt niet: gebruik het IP dat getoond wordt in [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] → “[[acc.addresses]]”.",
  "t.1b69lfb8q23": "S-meter, vermogen, SWR en ALC aflezen.",
  "t.1b9f31ks7vh": "Stem de radio af op een PSK31-frequentie (bijvoorbeeld 14,070 MHz USB) of RTTY (14,080 MHz) en open [[nav.digi]]. Druk op “[[digi.rx.start]]” en breng “[[digi.freq.rx]]” op het signaal: de tekst verschijnt in het ontvangstvenster.",
  "t.1bbeh1fyud5": "Om vanuit het venster “Active calls” te roepen (dubbelklik, auto call en auto answer van LogHX) zet je in Aurora [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] › “[[ens.g.udp]]” › “[[ens.k.AcceptUDPRequests]]” aan. Zonder dit ontvangt LogHX alles maar kan het Aurora niet laten zenden.",
  "t.1bbrjbgcogc": "Voltooide QSO’s worden vanzelf gelogd; “[[fox.drop]]” stopt een QSO die niet antwoordt.",
  "t.1be0izs5xg3": "Terwijl je zendt pauzeert de waterval (de radio levert dan geen audio) en hervat bij ontvangst; een gele lijn markeert de pauze. In het menu “[[wft.spec]]” verbergt “[[wfs.specOff]]” het spectrum; sleep de grijze balk boven het spectrum om de hoogte te wijzigen.",
  "t.1bf7d5bdxj7": "Rijen van Fox-stations (DXpedities in Fox/Hound) tonen het hele bericht, de vlag en het land van de Fox (de roepnaam tussen < >) en het label FOX.",
  "t.1bma4yxjowx": "Bezette COM-poort met naam, geduldiger OmniRig, trage pc",
  "t.1bqiwx44wex": "Tx-frequentie buiten 200-2700 Hz",
  "t.1bqrilyqez9": "Voor de meest voorkomende radio's toont Aurora “[[cat.preset.title]]” in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]], met een knop die de waarden invult.",
  "t.1btu5hbhorw": "Controleer of telefoon en pc in hetzelfde thuisnetwerk zitten en Aurora open staat op de pc.",
  "t.1c6cl5docfs": "Als het station dat je oproept niet antwoordt, klik je in het paneel [[panel.tx]] op een roepnaam in de wachtrij: Aurora laat het huidige QSO vallen en antwoordt dat station. De kleine knop » springt naar de eerste in de wachtrij.",
  "t.1cidydnyqia": "Log dicht: de QSO’s komen later",
  "t.1civmd3xnne": "In [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]], groep “[[lotw.grp]]”: “[[lotw.enable]]” (standaard aan), “[[lotw.color]]” en “[[lotw.months]]” (3, 6, 12 of 24 maanden, of “[[lotw.m0]]”). Alleen stations die binnen die maanden hebben geüpload tellen mee.",
  "t.1co4yf0orvq": "Kleuren van gewerkte en bevestigde vierkanten op de DX-kaart",
  "t.1cqhf6dpgu4": "Druk op Toepassen of Opslaan en dan op [[auto.turnOn]]. Probeer eerst [[auto.modeDry]]: het [[auto.log]] zegt wie het zou hebben beantwoord (groen), wie het heeft overgeslagen en waarom (oranje) en wat het blokkeerde (rood). Schakel als je klaar bent op de pc met de schakelaar in de kop over naar [[auto.modeLive]]: Aurora vraagt je de melding te bevestigen (het zendt vanzelf, jij blijft verantwoordelijk, ARRL en DXCC accepteren geen volledig geautomatiseerde QSO’s); terug naar [[auto.modeDry]] vraagt geen bevestiging.",
  "t.1cvpjlcxo6b": "De waterval",
  "t.1cy2rmaiube": "Rechtsklikken op een vakje van de onderste balk opent een klein menu: Squelch, AFC, Lock, Snap, squelch-drempel, UTC-klok en knipperende TX.",
  "t.1dbblkhy5yq": "Kies in “[[digi.ms.title]]” “[[digi.cw.bandwidth]]”: 150 Hz past bijna altijd; smaller (50-100 Hz) haalt ruis en nabije stations weg. Met de AFC aan haakt de toon in op het station, ook als het enkele tientallen Hz ernaast ligt, en volgt het als het verloopt; bij alleen ruis blijft hij stil.",
  "t.1dcx5gmduil": "De antennerotor",
  "t.1dm6lab91ge": "Bij “[[acc.devices]]” zie je de gekoppelde telefoons; “[[acc.revoke]]” verwijdert er één.",
  "t.1dmqqrp2y4u": "Stel voor de rotor deze in via [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]] en schakel “[[sat.ctl.rotor]]” in: hij volgt azimut en elevatie van de gekozen satelliet en gaat vlak voor de overkomst naar het punt waar die opkomt. In de radar is de blauwe ring waar de rotor naartoe wijst.",
  "t.1do9cq95i3r": "Wie naar u luistert, moet dezelfde modus en dezelfde T/R-periode gebruiken.",
  "t.1dpxr2d2f2o": "Gebruik je ook JTAlert: in BBLogger gaan de rijen “Msg ID 5” en “Msg ID 12” naar de poort van JTAlert, 2334, niet 2237.",
  "t.1eff0n83tkc": "“[[fil.always]]”: deze stations worden getoond, ook als een ander filter ze zou verbergen.",
  "t.1egmx0libb9": "WSPR-modus en uploaden naar WSPRnet",
  "t.1epsndesd4m": "Aurora: [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] → “[[ens.g.adif]]”: zet “[[ens.k.EnableUDP2adifBroadcast]]” aan, 127.0.0.1, poort 2237.",
  "t.1exbrfu4sa3": "Proceduretekens verschijnen als <AR>, <BT>, <KN> en <SK>; zo geschreven in de zendtekst of in een macro gaan ze als één teken de lucht in.",
  "t.1f04krwe5t5": "De telefoon toont bevroren gegevens of een oude versie na een update van Aurora.",
  "t.1f0xpqorm5m": "Als er een nieuwe versie is, verschijnt bij het opstarten midden in beeld een poster met wat er nieuw is: “Installeren en herstarten” installeert hem, “Later” verbergt hem tot de volgende versie. Intussen downloadt Aurora hem zelf op de achtergrond en controleert de handtekening: een kleine oranje balk bovenaan toont de voortgang en daarna “Klaar · Installeren en herstarten”, zodat de installatie meteen start zonder op de download te wachten.",
  "t.1fbynbj1khn": "BBLogger: QSO’s via het netwerk (UDP), aanbevolen",
  "t.1fgcfe9xk6i": "Is de Fox echt? OTP-controle",
  "t.1fkp4b2umao": "Aurora is nu «Aurora — Multimode Ham Radio Station», met het nieuwe pictogram: alle modi (FT8…MSK144, PSK, RTTY, CW, SSTV, satellieten) in één programma. JT65 heeft submodi A, B en C (EME) en middeling over perioden, gecontroleerd tegen WSJT-X. MSK144 heeft een periode van 5/10/15/30 s die per band wordt onthouden en korte berichten «Sh». Instellingen › Filters › Decoderen bevat de WSJT-X-opties: diepte, Single decode, middeling en Auto Clear Avg, JT65 AP en deep search, F Tol. Nieuwe SSTV-pagina en handleiding «De radio aansluiten».",
  "t.1fnpzfaxspr": "Als een ander programma de poort van de radio vasthoudt, zegt Aurora welk (OmniRig, WSJT-X, JTDX, Log4OM…). OmniRig dat nog opstart of met de radio uit geeft een melding in plaats van een fout, en de PTT blijft nooit aan. Op een trage pc stelt de waarschuwing «Naar Normaal» voor. Het rapport in Commando’s volgt het verzonden rapport (#38). Statusbalk van PSK·RTTY·CW zonder datum en tijd; veiliger «Aanzetten» voor de FT-2000.",
  "t.1fqh90ijfq3": "Druk op “[[sstv.tx.send]]”: de radio zendt en de balk toont de voortgang; “[[sstv.tx.stop]]” schakelt audio en PTT meteen uit. Het verzonden beeld blijft in “[[sstv.hist.sent]]”.",
  "t.1fs895wiqqz": "[[bak.intro]]",
  "t.1ftn1bujepw": "Eén programma per poort: een COM-poort kan maar door één programma worden geopend. Sluit WSJT-X, JTDX, logprogramma's en al het andere dat de radio gebruikt. Heb je ze samen nodig, leid ze dan via OmniRig of Cat4OM: Aurora ondersteunt beide ([[cat.backend]] → “[[cat.backend.omnirig]]” of “[[cat.backend.cat4om]]”).",
  "t.1fvn5dw2z7d": "Open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], vak [[gen2.wsjtx3]].",
  "t.1fy81t10wtq": "Start rigctld onder Linux niet? De melding geeft de reden die Hamlib opgeeft (met zijn regels): lees die om te zien of model, poort of snelheid fout is. Een Icom op 4800 baud opent langzaam: Aurora wacht tot 15 seconden.",
  "t.1fywh51m8no": "[[cat.port]]: de COM-poort van de radio. [[cat.baud]]: dezelfde als in het CAT-menu van de radio.",
  "t.1g14b1xuwj": "Bovenaan band en modus: als je zendt, vraagt Aurora om bevestiging voordat het ze wijzigt.",
  "t.1g33cb29v7": "De onderste balk toont S/R (in 3 kHz, zoals WSJT-X) en de herkende snelheid. De squelch kijkt naar diezelfde S/R, niet naar het volume; ook uitgeschakeld wordt onder ongeveer -16 dB niets afgedrukt, zodat ruis het venster niet vult. Probeer bij een onregelmatige handsleutel “[[digi.cw.som]]”.",
  "t.1gaua23kzwe": "In [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[nav.automation]] kan Aurora vanzelf de CQ’s beantwoorden die je iets nieuws opleveren. De kop toont altijd of het aan staat, in welke modus en wat het vandaag heeft gedaan; eronder staan vijf blokken regels, elk met zijn eigen “?”.",
  "t.1gd8yjcywop": "Onder de roepnaam van de zender, in Bandactiviteit en het RX-venster, geeft een gekleurde balk aan dat dat station LoTW gebruikt: het loont om het te werken als je de bevestiging wilt.",
  "t.1gf93sotihm": "De keuzelijst “[[digi.band.validation]]” in het paneel bepaalt hoe streng roepnamen worden gecontroleerd: Aurora telt hoe de roepnamen van elk land zijn opgebouwd (uit het log, de DX-clusterspots en MASTER.SCP, als je die in de gegevensmap van Aurora zet) en een roepnaam met een zeldzame vorm moet meerdere keren gehoord worden voordat hij telt. Lokale spots bevatten de S/R in 500 Hz gemeten met ingedrukte seinsleutel (mediaan van de laatste 15 seconden), de WPM en CQ of DE; hoogstens één per roepnaam en band per 10 minuten, opnieuw als het station meer dan 1 kHz verschuift of CQ begint te roepen. Met “[[digi.band.spotsCqOnly]]” alleen stations die roepen.",
  "t.1gl50njtlnr": "[[cat.cat4om.management]]: standaard 127.0.0.1:17300, de beheerpoort van Cat4OM. Van daaruit vindt Aurora zelf de groep en de Control-poort ervan (Cat4OM kent die toe aan de groep, bijvoorbeeld 5001), zoals Decodium met “Automatic discovery”. Laat [[cat.cat4om.group]] en [[cat.cat4om.address]] leeg: na het verbinden verschijnen de gevonden waarden in grijs. Vanaf een andere pc vult u het adres van de Cat4OM-pc in en zet u netwerk aan in Cat4OM.",
  "t.1gqm5n6ej0y": "WSPR-2 kies je in de modusselectie: perioden van twee minuten, alleen baken, zoals WSJT-X. Naast de modus staan het vermogen, [[mode.wsprPct]] (standaard 20%, met de tweeuurstabel van WSJT-X) en [[mode.wsprType1]]; er wordt alleen gezonden met [[ctl.enable_tx]] aan, tussen 1400 en 1600 Hz. De waarde van [[mode.wsprPct]] wordt verstuurd als je Enter drukt of het veld verlaat.",
  "t.1grwql0zdh5": "Als Log4OM na een update van Aurora OFFLINE toont, druk dan op “Save and apply” om opnieuw te verbinden.",
  "t.1gta7bmh47n": "De bovenbalk",
  "t.1gx542y76na": "De kaart in het logboekpaneel",
  "t.1he4qqxg96l": "FST4 en FST4W kiest u in de moduskeuze, met de T/R-periode naast de modus, zoals in WSJT-X: FST4 van 15 s tot 30 min, FST4W van 2 tot 30 min. FST4 is voor QSO’s met zwakke signalen, met berichten en volgorde zoals FT8. FST4W is een baken zoals WSPR: geen QSO’s, ontvangen berichten starten de volgorde niet.",
  "t.1hj2sohcl7e": "[[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]: [[cat.backend]] TCI, adres 127.0.0.1:40001, daarna [[cat.connect]].",
  "t.1hp88zw2v6h": "Je kunt kiezen wanneer het FT8-decoderen start en of er wordt gedecodeerd terwijl je zendt.",
  "t.1hv0xay4d2l": "In het radiomenu: de opties die in het vak staan (CAT-snelheid gelijk aan Aurora, data-audio via USB).",
  "t.1hv4w7adw06": "Met de pagina open blijft het luisteren aan tot je op «Luisteren stoppen» drukt en het hervat vanzelf na je uitzending. In het log wordt de roepletters meteen opgezocht op QRZ.com of HamQTH en vult naam, QTH en Locator in; de pagina is compacter, met Ontvangen en Verzonden in een kolom rechts.",
  "t.1hvhseyxun": "Met Hamlib toont het display de echte waarden van de radio: S-meter bij ontvangst, vermogen bij zenden.",
  "t.1i1dnjh9bqo": "[[wfs.palette]]: 30 paletten plus een eigen palet. [[wfs.gain]] en [[wfs.zero]] maken signalen en achtergrond helderder of donkerder.",
  "t.1i82ocqi7j9": "In Hound-modus roept Aurora nooit CQ. Expedities die SuperFox gebruiken (een breed signaal dat tot 9 stations beantwoordt) worden nog niet door Aurora ontvangen: dat komt in een latere versie.",
  "t.1iackvfo1m5": "Om een QSO te volgen dubbelklik je op het station in Bandactiviteit: de RX-frequentie springt ernaartoe en het RX-venster volgt die QSO. Standaard blijven de berichten ook in Bandactiviteit staan; wil je ze alleen in het RX-venster, schakel dan “[[rxw.exclusive]]” in het vak “[[fil.grp.rx]]” in.",
  "t.1ie22j7uhnc": "Alleen VFO A wordt gebruikt: bij split verschuift Aurora de frequentie alleen tijdens het zenden (geëmuleerde split). Zegt de status dat FT-991(A) Link niet antwoordt, controleer dan of in FT991Link de poort open is en UDP is gestart.",
  "t.1iez95k7u8": "Boven de waterval decodeert het paneel “[[digi.band.title]]” alle CW-signalen in de audioband tegelijk, elk met een eigen ontvanger: één regel per signaal met frequentie, WPM, S/R, roepnaam (vlag, CQ of DE; cursief zolang hij niet bevestigd is) en laatste tekst, met onzekere tekens in grijs. De roepnaam staat ook in de waterval boven het spoor. Een klik zet de ontvangst op dat signaal, een dubbelklik toont alle tekst van de laatste 60 seconden. Aan- en uitzetten gaat in het menu Opties (“[[digi.band.mi]]”); bij te veel signalen blijven de sterkste, zodat niet meer dan een kwart van een kern wordt gebruikt. Bevestigde roepnamen komen als lokale spots in het DX-clusterpaneel van Aurora (“[[digi.band.spots]]”): ze blijven op je pc, er gaat niets het netwerk op.",
  "t.1ihn4r86q5b": "Zet “[[int.adif]]” (Log4OM, WaveLogGate) of “[[int.n1mm]]” (HRD Logbook) aan, daarna “[[int.resend]]”. Zonder een van de twee formaten blijft het vakje grijs.",
  "t.1ijmmk4nzub": "Zo hebben logboek, spots en kaart de juiste band. Aurora onthoudt het ook als je het opnieuw opent.",
  "t.1im8b9iac81": "Druk op “[[digi.tx.send]]” (of Ctrl+Enter): de radio zendt en de balk toont de voortgang; “[[digi.tx.stop]]” stopt meteen. De tekst die je hebt verzonden verschijnt in het venster, voorafgegaan door ».",
  "t.1infs1rz0m4": "De Pwr-schuifregelaar",
  "t.1ipvfcy7jl": "De telefoon wordt niet bijgewerkt",
  "t.1iq5jajdaiy": "Bovenaan Tx, Rx en Rapport; eronder een rij knoppen.",
  "t.1iswnykcbwh": "“[[cluster.callsign]]”: veel servers willen een echte roepnaam om in te loggen.",
  "t.1itogjsvb7a": "In “[[contest.order.value]]” komen de berichten die je kunt beantwoorden eerst (CQ, QRZ en stations die jou roepen), daarna QSO’s tussen andere stations; “[[contest.onlyCq]]” verbergt die laatste. “[[contest.dupe]]” markeert stations die al op deze band zijn gewerkt en, als ze elders nog meetellen, de banden waar ze meetellen; dubbelklikken op een dupe vraagt om bevestiging. In multibandcontesten is dezelfde roepnaam op een andere band een nieuwe QSO: Aurora beantwoordt hem. Onder de tips staat, bij meer dan één band, een klein tabelletje met QSO’s, punten en multipliers per band. F1–F4 doen niets terwijl je in een veld typt of een venster open is.",
  "t.1iv4h5nm42k": "Het bandmenu begint op “[[dxmap.bandNow]]”: locatorvelden en PSK Reporter-spots van de band waarop je zit, in real time (een paar seconden) en elke 10 seconden ververst. “[[dxmap.onlyHeardMe]]” houdt alleen de lijnen naar stations die jou ontvingen; “[[dxmap.callLabels]]” schrijft de roepnamen altijd (uit, dan verschijnen ze bij muisaanwijzing). Tijdens het zenden loopt een rode lijn naar het station dat je oproept. Het tabblad “Kaart” van het logboekpaneel toont dezelfde kaart.",
  "t.1izvi4ybfcg": "Yaesu FTdx101D/MP, FTdx10, FT-991A, FT-710: de USB-kabel maakt twee virtuele COM-poorten aan (Silicon Labs CP210x). “Enhanced COM Port” is voor CAT, “Standard COM Port” voor PTT en CW-keying. Kies bij [[cat.rig]] het model met de naam van de radio; stel de CAT-snelheid in het radiomenu in (optie CAT RATE, zie de handleiding) en dezelfde bij [[cat.baud]].",
  "t.1j13tbe6io0": "Drie controles stoppen het zenden wanneer het niet de lucht in mag; het Tx-paneel toont de reden.",
  "t.1j407n77sut": "Download het installatieprogramma (Aurora_X.Y.Z_x64-setup.exe) van de Releases-pagina van Aurora op GitHub en voer het uit.",
  "t.1jip06idvcu": "Oplossingen: PTT, lange zendingen, DXCC-landen, Wait and Call, GridTracker en ADIF-logboek",
  "t.1jm15df0wi2": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]]: druk op “[[sup.prepare]]”.",
  "t.1jm5milpljm": "PSK, RTTY en CW: open zendstand",
  "t.1jnndslg531": "De pagina [[nav.sat]] toont op een wereldkaart, met dag en nacht, waar de amateursatellieten zijn, hun passages boven jou, een hemelradar en de baangegevens. Hij kan ook de Doppler op de radio corrigeren en de rotor laten draaien om de satelliet te volgen.",
  "t.1jvsvcu4nl7": "[[cat.split]]: “[[cat.split.rig]]” (Rig) doet een echte split in FT8 en FT4 met CAT-PTT: de zend-VFO verschuift en de audio blijft tussen 1500 en 2000 Hz, zoals in WSJT-X. “[[cat.split.emulate]]” (Fake It) verplaatst de frequentie alleen tijdens het zenden. Beide werken met Hamlib, TCI en OmniRig; FT-991(A) Link kent alleen Fake It. Als je de Tx-frequentie tijdens het zenden verplaatst, volgt de radio meteen.",
  "t.1jwirwgfgpk": "[[auto.b2]]: bij meerdere CQ’s in dezelfde cyclus kiest Aurora er maar één, de zeldzaamste, de sterkste of de beste op score.",
  "t.1jxdcn44rxh": "Status “[[rot.state.error]]”: controleer of de COM-poort die van de rotor is (niet die van de radio) en dat geen ander programma hem open houdt; Aurora probeert het zelf opnieuw.",
  "t.1k40irhkrpr": "Alleen de roepnaam van de Fox, de tijd en de code gaan naar de controledienst. SuperFox heeft een eigen controle die Aurora nog niet ontvangt.",
  "t.1k5870uxnfx": "Het handigste: “call to me”. Het rinkelt telkens als een station je antwoordt.",
  "t.1k9s0u3njsw": "Een klik op de waterval bij alleen ontvangen verplaatst de zendfrequentie niet meer als “Hold Tx Freq” aan staat. Nadat de radio opnieuw is verbonden, herstelt Aurora de gekozen split. De lijsten met gewerkte stations en stationkaarten groeien niet meer eindeloos, de logboeken van de engine rouleren naar een oud bestand boven 20 MB, en een onleesbare lijst met bekende roepnamen wordt niet meer leeg herschreven. Het logboek waarschuwt nu voor cty.dat-regels met een ongeldige kop en voor Wavelog- of Cloudlog-adressen die http:// over internet gebruiken.",
  "t.1ka7aipksik": "Klik op de waarschuwing: [[nav.settings]] › [[sw.sec.station]] › [[tab.clock]] opent, met de NTP-servertest.",
  "t.1kalhnd5his": "“[[int.title]]”: meer programma’s, elk met adres, poort en wat het ontvangt. Knoppen: “+ [[int.p.wsjtx]]” (2237), “+ [[int.p.adif]]” (2333), “+ [[int.p.multicast]]” (239.255.0.1).",
  "t.1kbe0eun7no": "Lukt het nog steeds niet? Stuur wie je helpt de exacte foutmelding die je ziet, of het ondersteuningspakket: [[nav.settings]] › [[sw.sec.access]] › [[tab.support]] → “[[sup.prepare]]”. Het bevat de logboeken en de instellingen, zonder wachtwoorden.",
  "t.1kbuel2sbk": "Kies in [[gen2.decStart]] [[gen2.decStartEarly]] voor meer tijd om te antwoorden, [[gen2.decStartLate]] om late signalen te vangen; standaard [[gen2.decStartNormal]].",
  "t.1kil71ov64s": "Het paneel is in de hoogte verdeeld: bovenaan de CQ’s in een horizontale strook van twee rijen (één station per vakje; als er meer zijn dan er passen, scrolt het vanzelf en stopt onder de muis); eronder de DXpedities, één regel per stuk, met vlag en datum, ook die binnen 120 dagen komen.",
  "t.1kppp22q67t": "Elk QSO kan rechtstreeks naar eQSL, Wavelog/Cloudlog, ClubLog, QRZ.com, HRDLOG.NET en LoTW, zonder tussenliggend programma.",
  "t.1kppryvgfgk": "Schakel het in bij Instellingen › Station › SDR · TCI · QMAP → “QMAP page in the menu”: het item QMAP verschijnt bovenaan.",
  "t.1kqsisk9emz": "Als het installatieprogramma oud was, verschijnt bij de eerste start eerst de poster van de nieuwe versie: druk op “[[upd.poster.install]]”, Aurora werkt zichzelf bij, start opnieuw en pas dan begint de gids. Met “[[upd.later]]” begint de gids meteen.",
  "t.1l3myjbzmek": "Band Hopping",
  "t.1lge3qmk75c": "Telefoon en tablet",
  "t.1lhdhm58fjg": "De PTT is degene die in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] is gekozen (CAT met Hamlib of OmniRig): controleer dat hij niet op VOX is blijven staan.",
  "t.1lrb6q7rlcm": "Dubbelklik op een spot met «UP 5», «5UP» of «QSX» in het commentaar: de radio gaat in split op VFO B. Cat4OM vindt zelf de groep en de poort, zoals Decodium. Interface, handleiding en installatieprogramma ook in het Nederlands; bij de eerste start gebruikt Aurora de taal van Windows. FST4W zendt als baken en, als u het aanzet bij Online diensten, stuurt Aurora WSPR- en FST4W-spots naar WSPRnet (standaard uit).",
  "t.1lzye0fj3xq": "Op de pagina Radio toont «Zoeken» de groepen en radio’s van Cat4OM met hun status en kiest «Gebruiken» de gewenste. Audio gaat ook via het netwerk, bij ontvangst en zenden: op het tabblad Audio staat het apparaat «Cat4OM (netwerkaudio)». De stream wordt vóór de PTT geopend en fouten zijn duidelijk.",
  "t.1m7yrckldff": "JT4 (submodus A) kies je in de modusschakelaar, zoals JT65 en JT9: periodes van een minuut, vier tonen 4,375 Hz uit elkaar. De officiële JT4-frequenties liggen op de microgolven; op HF-banden gebruiken de knoppen de JT65-frequentie.",
  "t.1m9zx7xpvhy": "Het Rx-venster staat standaard aan, zoals «Rx Frequency» in WSJT-X: het toont berichten rond de ontvangstfrequentie, die aan jou gericht zijn en je eigen zendingen; zet het uit met de RX-knop en de keuze wordt onthouden (#42). De knop «Spot DX» staat nu ook op de pagina Station, in FT8 en de andere modi, en de spot die je verstuurt verschijnt meteen in de clusterlijst onder je roepnaam. De split «Rig» en «Fake It» werkt nu echt in FT8 en FT4 met CAT-PTT: de audio blijft tussen 1500 en 2000 Hz en de zend-VFO verschuift, zoals in WSJT-X (te testen met de radio).",
  "t.1mazfrzlv4e": "Als de COM-poort van de FT-991 wordt vastgehouden door het programma FT-991(A) Link, stuurt Aurora de CAT-commando's via UDP: frequentie, mode en PTT, zonder om de poort te vechten.",
  "t.1mf289yh8w0": "Berichten die tijdens je zending worden gedecodeerd worden getoond, maar de reeks beantwoordt ze niet.",
  "t.1mmnuixmr07": "QMAP luistert tegelijk naar een stuk tot 90 kHz breed en decodeert elk Q65-signaal dat het vindt: handig op 6 m, 2 m en EME, waar stations over veel frequenties verspreid zijn. Alleen voor bezitters van een SDR-ontvanger: met een gewone radio (FT-2000, IC-7300 en dergelijke) heeft het niets om te lezen.",
  "t.1mn51tsi8yr": "De PSK-ontvanger volgt nu het model van fldigi: betere filters, nauwkeurigere synchronisatie, een squelch op basis van signaalkwaliteit en een AFC die niet meer over de ruis zwerft. Letters met accent worden ook ontvangen. Bij het zenden begint en eindigt het signaal zonder «klik». In de vergelijkingstest dalen de fouten in PSK31 van 56,8% naar 17,2%.",
  "t.1moo47q4zlj": "Open in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] het vak “[[toast.grp]]”.",
  "t.1n0sg4vvbuz": "[[auto.b1]]: vink de nieuwigheden aan die je wilt (nieuw land, nieuw op de band, [[auto.newMode]], grid, zone) en het minimale signaal.",
  "t.1n2v06cxt7k": "De pagina [[nav.contest]] doet alles in één programma: berichtenreeks van de contest, dupes, punten, multipliers, live score, rate en het bestand voor de organisator. De regels van WW Digi, ARRL Digi, ARRL Field Day, FT Challenge, ARRL VHF, CQ WW VHF, IARU MGM 50/70 MHz, EU VHF, ARI FT8 Activity, DARC FT4, RSGB FT4, PACCdigi, YBDXPI FT8, VHF-UHF FT8 Activity (EU en NA), NCCC FT4 Sprint en een «Custom» contest zijn inbegrepen.",
  "t.1n7uspiqh1n": "Om op de snelheid van de roeper te antwoorden gebruik je “TX op ontvangen snelheid” in het menu [[digi.menu.mode]], of de knop “[[digi.st.txAtRx]]” in de onderste balk: de zendsnelheid wordt die welke bij ontvangst is gemeten, afgerond op hele WPM. Dit werkt alleen als de ontvangst aan staat en er een signaal is.",
  "t.1n8jooh9mjh": "De audio-ingang en -uitgang van de radio kiezen.",
  "t.1n9ybcyuosc": "Dubbelklik op de spot (enkele klik op de pagina’s PSK, RTTY en CW, als je die hebt gekozen): ontvangen (VFO A) op de spot, zenden (VFO B) verschoven, split aan. Boven de tabel verschijnt “Split DX: Tx 14.030” met de knop “[[cluster.splitDx.off]]”.",
  "t.1nbztqomue9": "Laat Log4OM de radio lezen via Aurora (gedeelde CAT).",
  "t.1ndvgssh1u4": "Kies wat er getoond wordt in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]], vak “[[cqp.title]]”: soorten berichten, alleen bepaalde stations, te verbergen stations, maximaal aantal rijen.",
  "t.1nhqsuwcwtc": "Op het spectrum onder het beeld helpen vaste merktekens bij het afstemmen: de synchronisatie moet op de gele lijn van 1200 Hz vallen, zwart op 1500 en wit op 2300 (de gestippelde lijnen zijn de VIS en de voorloopton). Zodra Aurora de afwijking heeft geschat, toont een rode lijn waar de synchronisatie echt ligt. Onder het beeld toont “[[sstv.clean.cleaned]]” het van ruis ontdaan, ook terwijl het binnenkomt; het origineel verandert niet.",
  "t.1nkuvsk2v0q": "Standaard aan, je kunt ze uitschakelen: ze helpen problemen op te lossen zonder persoonlijke gegevens te sturen.",
  "t.1npskixhuze": "De pagina [[nav.digi]] ontvangt en verzendt tekst in PSK31, PSK63 en RTTY met dezelfde geluidskaart en PTT als FT8, zonder FT8 te storen. Kies de modus bovenaan, of met de PSK- en RTTY-knoppen in het menu.",
  "t.1nsus64hw9x": "Open [[nav.contest]], kies de contest in het menu en druk op “[[contest.activate]]”. Aurora stelt berichten en CQ-woord, exchange, Fox en Hound uit, AutoSeq aan, Hold Tx Freq en modus in; wat er eerst stond wordt onthouden.",
  "t.1nxf0wro3n0": "Kies bij “[[digi.scan.title]]” hoe lang je op elk station blijft (“[[digi.scan.dwell]]”), of je bij het eerste stopt (“[[digi.scan.once]]”) en of de tijd en de frequentie van elk station in de tekst worden afgedrukt.",
  "t.1nz9r3nc6ik": "Je kunt het venster vergroten of verkleinen of het paneel verplaatsen: de waterval behoudt de reeds getekende rijen.",
  "t.1nzr1mxhurj": "Laat QMAP uit bij de FT-2000 of andere radio’s zonder I/Q-stream: voor gewone Q65 volstaat de modusschakelaar op de pagina Station.",
  "t.1o19je3tq73": "Er is één contestlogboek per editie (de begindag staat in de bestandsnaam), zodat wekelijkse en maandelijkse contesten niet door elkaar lopen; logboeken van eerdere versies worden nog gelezen. Als de contest eindigt blijft het logboek zoals het is en is de fase twee dagen “beëindigd”: Aurora verwijdert nooit zelf QSO’s, ook niet als je begin en einde met de hand wijzigt. Het serienummer is altijd het aantal QSO’s in het contestlogboek + 1, ook na een verworpen QSO of “Reset”. In de Cabrillo blijft een ontbrekende exchange “-” en de controle meldt het; QSO’s op banden die de regels niet toestaan worden weggelaten, met een waarschuwing; CATEGORY-TIME en CATEGORY-OVERLAY worden alleen geschreven als je ze in de instellingen invult.",
  "t.1obc2l726hm": "De Instellingen zijn nu verdeeld in vijf gekleurde families (Station, Modi, Logs clusters en diensten, Uiterlijk en meldingen, Toegang en ondersteuning), met pagina’s die als een harmonica openklappen; elke modus heeft zijn eigen tak en het tandwiel van elke pagina opent de juiste. Er zijn nieuwe pagina’s: Persoonlijke gegevens, Scannen en geheugens voor PSK · RTTY · CW, en de Contest gesplitst per modus. Dubbele items zijn weg: het loggen van QSO’s staat op één plek.",
  "t.1oc2ghw18qs": "Kies op de QMAP-pagina onder “I/Q source” “SDR via TCI” met het adres (bijv. 127.0.0.1:40001) of “I/Q WAV file” met het pad; daarna periode en submodus (bijv. 60 s, A) en “Apply”. “+30 s” zoekt ook naar Q65-30, “Average” telt periodes bij elkaar op voor zwakkere signalen.",
  "t.1ofxzbd7vfn": "Om meteen naar het volgende item te springen, zonder te wachten, rechtsklik je op de bandbalk.",
  "t.1ogjcw0u5am": "[[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]: [[cat.backend]] FT-991(A) Link (UDP), [[cat.ft991.address]] 127.0.0.1:50001 (of de in FT991Link ingestelde), daarna [[cat.connect]].",
  "t.1olh8317ke6": "De ontvangstpagina heeft ook de knop “[[sstv.rx.tx]]”: die zendt het beeld dat in “[[sstv.view.tx]]” is voorbereid en brengt je daarheen. Als de zending eindigt, gaat de pagina vanzelf terug naar ontvangen, dat nooit is gestopt: je kunt ook het volgende beeld voorbereiden terwijl er een binnenkomt.",
  "t.1ovap98yqn3": "Jouw station",
  "t.1p526ct6pav": "De roepnaam van de zender staat vet in het bericht, zodat je hem meteen ziet; de volgorde blijft die van FT8 (aan, van, info).",
  "t.1pfa920qxem": "De pagina Satellieten heeft nu een eigen wereldkaart, «Aurora-kaart», met land en grenzen onder dag en nacht, sporen en footprints van de satellieten; de beeldkaarten die je toevoegt blijven in de lijst te kiezen. Onder Linux gebruikt het geluid PulseAudio en PipeWire en toont het dezelfde apparaten als WSJT-X en JS8Call. CAT werkt nu ook met radio’s die geen Icom zijn en met de Hamlib van Debian 12, en PTT via RTS met het model Dummy («alleen PTT») werkt. De lijst met /dev/ttyUSB-poorten is beschikbaar en Aurora wacht langer op trage Icom-radio’s.",
  "t.1piztfaz526": "Druk op de pagina [[nav.station]] op de band (bijvoorbeeld 40m): Aurora stelt zijn eigen frequentie in voor die band en mode, zonder de radio aan te raken.",
  "t.1pm1q9uo0va": "[[cat.cat4om.key]]: het wachtwoord van de groep, alleen als de groep erom vraagt (anders leeg). [[cat.cat4om.radio]]: de naam van de radio in Cat4OM (bijvoorbeeld kenwood/ts-990), niet de naam van de groep; leeg = de eerste beschikbare radio. Antwoordt de beheerpoort niet of vraagt hij om een wachtwoord, vul dan in [[cat.cat4om.address]] de “Control”-poort van de groep in die Cat4OM of Decodium toont (bijvoorbeeld 127.0.0.1:5001).",
  "t.1pm3ikhiwro": "In een contest schakelen “Enable Tx” en Auto CQ zichzelf niet meer uit: als een QSO eindigt (of de DX aan iemand anders antwoordt, of de watchdog afgaat) wordt het station vrijgegeven en gaat het meteen terug naar CQ. Alleen jij stopt het, met Esc of het TX-vierkant. Bij standaardberichten (bijvoorbeeld DARC FT4) schakelt “Skip Tx1” zichzelf uit bij activering, zodat het eerste bericht de locator bevat en de uitwisseling volledig wordt verzonden.",
  "t.1pq1etxtlh2": "Vanaf een telefoon of tablet in het thuisnetwerk bedien je Aurora dat op de pc draait.",
  "t.1psrttb03bl": "De klok",
  "t.1q4vbcjsu3r": "Dubbele QSO’s: hetzelfde logboek ontvangt via twee wegen (stroom, ADIF, doorsturen vanuit GridTracker of JTAlert). Houd er maar één.",
  "t.1q8zhxoi4t9": "Links de zon en de bandcondities; rechts de kaart en de lijst van wie jou ontving (PSK Reporter): nieuwe ontvangstrapporten komen in realtime binnen, binnen enkele seconden, en de pagina wordt elke 10 seconden vernieuwd. Standaard aan; schakel het uit in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].",
  "t.1q94x7z71zt": "CW: ontvanger vernieuwd en een AFC die werkt",
  "t.1qq3b86nnjf": "Met [[ctl.answer_all]] aan wordt elk station dat je roept vanzelf in de wachtrij gezet.",
  "t.1qv03nv9ppk": "Het wordt aan- en uitgezet in [[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]] met “[[cluster.splitDx.set]]” (standaard aan; het “?” ernaast legt alles uit).",
  "t.1qyl3k2z4ne": "PRE en ATT: vanuit uit doorlopen ze de waarden die de radio accepteert (bijv. 10 en 20 dB) en gaan dan terug naar uit.",
  "t.1qzt5hlaj75": "De nieuwe decoder kiest de meest waarschijnlijke lezingen en heeft een filter tegen knetterstoringen: in de test dalen de fouten van 45% naar 24% (fldigi 74%). Het paneel «Signalen» decodeert elk CW-signaal in de band, één regel per signaal; roepletters worden op meerdere niveaus gecontroleerd en komen als lokale spots in de DX Cluster van Aurora terecht, nooit op het netwerk. De filterbandbreedte is direct aan te passen.",
  "t.1qzw01ou86a": "Het RX-venster, het log en Contest hebben goed zichtbare lijnen en kolommen die u verplaatst en verbreedt door de titels te slepen, zoals de DX Cluster. In de cluster toont de kolom Modus ook CW en SSB, uit het bandplan van IARU Regio 1 als het commentaar het niet zegt. De lijst met DXpedities toont naast het land de QSL-route (LoTW, OQRS, manager). Eén rotor op alle pagina’s; rechtsklik op een roepnaam opent QRZ.com.",
  "t.1r3dp264fbm": "Een zojuist gelogd QSO knippert bovenaan. Hoeveel QSO’s je ziet: [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] → “[[gen.log4omCount]]”.",
  "t.1rg6npr7jlo": "NB, NR, NOTCH en ATU: één klik zet aan, nog een klik zet uit.",
  "t.1rk1sgeorme": "Wachtwoorden en sleutels worden opgeslagen als je het veld verlaat of op Enter drukt: het veld toont dan “Opgeslagen ••••” met “Wijzigen” en “Verwijderen”, en de knop “Testen” van het vak draait vanzelf. De opzoeking in QRZ.com en HamQTH staat in “[[sw.fam.log]] › [[tab.online]]”: met de muis boven de DE-roepnaam in het DX Cluster zie je vlag, land en, indien aan, naam en plaats.",
  "t.1rpt7b90t8z": "De modus van DX Cluster-spots",
  "t.1rrugwu105r": "“Eerder gewerkt” uit het Log4OM-logboek: start Aurora met de variabele AURORA_LOG4OM_DB ingesteld op het pad van de Log4OM SQLite-database. Aurora leest die alleen, en het paneel [[panel.log]] toont de Log4OM-QSO’s.",
  "t.1rukb0zxmjb": "Ingang: de kaart die het geluid van de radio ontvangt (meestal “Microphone (USB Audio Device)”).",
  "t.1s2btcanvky": "Controleer de Rx-balk: die moet “Goed” zeggen.",
  "t.1s2n8ru7w0h": "CQ roepen",
  "t.1s7oy1wvrhd": "In PSK toont de onderste balk S/R en IMD (de IMD wordt gemeten tijdens de doorlopende faseomkeringen aan het begin van elke uitzending; onder -20 dB is het signaal schoon). De squelch kijkt naar de fasekwaliteit (0-100), niet naar het volume: bij 15 wordt ruis niet afgedrukt en komen signalen door tot ongeveer -10 dB. De AFC volgt het station alleen als er een PSK-signaal is, dus bij ruis blijft hij stil.",
  "t.1s9o0yvjsif": "Zet de Pwr-schuif hoger en let op de ALC op het display (onderdeel “De Pwr-schuif”).",
  "t.1seypt02j9w": "Aurora: verplaats de primaire server naar een andere poort (bijvoorbeeld 2238, of die van GridTracker), zodat 2237 vrij blijft voor Log4OM.",
  "t.1skl7kd3qfl": "Bij elke frequentiewijziging wordt de kaart leeggemaakt: alleen stations die daarna gehoord worden blijven staan.",
  "t.1smfhk5rg7r": "De knop na [[nav.wiki]]: de laatste wijzigingen van Aurora op een tijdlijn per versie, met gekleurde kaarten (nieuw, gewijzigd, opgelost) en de datum en tijd van de release in jouw lokale tijd.",
  "t.1smhh26ne7x": "Satellieten: passages, Doppler en rotor",
  "t.1sqciq6bwrk": "Kies in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] de stijl bij “[[rd.title]]”: elke stijl heeft zijn eigen voorbeeld.",
  "t.1ti1wh8oi3e": "JT65-submodi en middeling",
  "t.1tjjhwkzkwg": "Kies in “Fast QSO”, in het menu onder “Auto-Save”, Aurora en vink “Auto-Save” aan.",
  "t.1tl7lrbvmm4": "Elke QSO gaat naar het normale logboek en naar het contestlogboek. Als het andere station de exchange herhaalt na jouw RR73, zendt Aurora vanzelf opnieuw RR73 en markeert de QSO als “[[contest.state.incerto]]”; de ontvangen exchange wordt met één klik in het logboek rechtgezet.",
  "t.1tppo6ct1re": "De QSO’s komen na het openen niet aan: de poort van de bestemming moet die zijn waarop het log luistert (in Log4OM moet de verbinding ADIF_MESSAGE actief zijn).",
  "t.1tv61ps80tc": "Let op: met deze functies kan een zending starten zonder dat je iets indrukt. Wis de DX als de QSO klaar is.",
  "t.1u2tdrladea": "Log4OM 2: QSO’s ontvangen",
  "t.1u42db17y1s": "Kies bij een SDR met twee ontvangers RX1 of RX2 in [[cat.tci.receiver]]: frequentie, mode, PTT en audio gebruiken die ontvanger. RX2 wordt vanzelf ingeschakeld als hij uit staat.",
  "t.1u5zsuahxe5": "Schakel in het SDR-programma de TCI-server in (meestal poort 40001).",
  "t.1uazifalbvr": "Foutrapporten",
  "t.1ubbhhucq4e": "Controleer dat [[gen2.waitFeatures]] aan staat ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]; standaard aan).",
  "t.1ueewvblym0": "De PTT schakelt niet",
  "t.1uf12cu1n2b": "Interface: rechtsklikmenu en andere verfijningen",
  "t.1uh3h1boiav": "Log op een andere pc: van hieruit valt niet te weten of het open is, dus de QSO’s gaan zoals altijd meteen weg. Houd het log open of gebruik het rechtstreeks uploaden (Wavelog, ClubLog, QRZ.com), dat al een eigen wachtrij heeft.",
  "t.1ui7owwixdm": "“[[ens.g.adif]]”: “[[ens.k.EnableUDP2adifBroadcast]]”, [[ens.k.UDP2Server]] en [[ens.k.UDP2ServerPort]]. Het stuurt alleen het QSO als ADIF-tekst, één per datagram.",
  "t.1uoc8nlye95": "De status komt aan maar het QSO niet: zet in Aurora “[[int.loggedAdif]]” aan in de bestemming, of kies in BBLogger “UDP 5”.",
  "t.1v1qxpsjal1": "Kies de mode (FT8, FT4…) in de keuzelijst; de banden zijn de kleine knopjes ernaast: één klik om van band te wisselen.",
  "t.1v8iexpszal": "JT65-submodi: kies naast de modus A (tonen 2,69 Hz uit elkaar, HF en 6 m), B (dubbele afstand, EME op 2 m en 70 cm) of C (viervoudig, EME vanaf 23 cm); hij moet overeenkomen met die van je partner. In B en C zoekt Aurora naar één signaal, het sterkste binnen F Tol van de Rx-frequentie, meet de breedte en maakt de spectra dienovereenkomstig glad.",
  "t.1v8w9vban0e": "Wordt de sleutel geweigerd, controleer dan ook de pc-klok: Cat4OM ontvangt alleen een bewijs dat met de tijd is berekend, nooit de sleutel.",
  "t.1varj1btb3z": "Aurora en Log4OM besturen tegelijk dezelfde radio, via Cat4OM.",
  "t.1vatnchi4ar": "De stille update stopt niet meer als een antivirusprogramma het oude bestand vasthoudt: het installatieprogramma probeert het enkele seconden opnieuw en gaat dan toch door. Ontbreekt WebView2, dan installeert Aurora het zelf na jouw «Ja» en start daarna opnieuw.",
  "t.1vbead16du3": "In tekstvakken toont rechtsklikken alleen de nuttige items, met «Alles wissen»; bij ontvangst van PSK, RTTY en CW zet het menu roepletters, naam en rapport in de QSO en zoekt een dubbelklik op een roepletters die op. Roepletterskader met meer contrast, volledige DX Cluster-opmerking bij muisaanwijzing, rechtsklikmenu in de statusbalk en een duidelijkere melding als rigctld niet antwoordt.",
  "t.1vhb0bky0gd": "Het filter “[[cluster.filter.spotter]]” naast band en modus: “[[cluster.filter.spotterMine]]” toont alleen de spots van stations op jouw continent (wat te horen is waar jij zit); je kunt ook de gewenste continenten aanvinken.",
  "t.1vkiacik8st": "De Fox zendt onder 1000 Hz en beantwoordt meerdere stations tegelijk in dezelfde periode, met signalen naast elkaar.",
  "t.1vpu6tk7tdu": "Wacht tot je de Fox decodeert en dubbelklik dan op een van zijn regels: Aurora roept hem met roepnaam en locator.",
  "t.1vqq5ctcf3j": "Elke QSO gaat maar één keer weg: meteen als het log open is, of uit de wachtrij, nooit twee keer. De wachtrij blijft ook als je Aurora sluit (bestand log-in-attesa.json in de gegevensmap); een QSO die langer dan zeven dagen wacht, wordt weggegooid.",
  "t.1vvcjb9w30": "Voeg een inkomende UDP-verbinding toe: type ADIF_MESSAGE, poort 2237 (dezelfde als Aurora); schakel hem in en druk op “Save and apply”.",
  "t.1w8gehzutgk": "Zet “[[cat.auto]]” aan zodat je het niet bij elke start hoeft te doen, en “[[cat.extras]]” voor het uitgebreide display. Deze twee vinkjes worden meteen opgeslagen.",
  "t.1wkdh41n1we": "Een klik op de roepnaam of het puntje: Aurora roept dat station op.",
  "t.1wye7ubzpuj": "Onbevestigd te onderscheiden en een waarschuwing voor de Tx-frequentie",
  "t.1x130kzrk9g": "[[toast.test]] toont ze je meteen.",
  "t.1xkf712npo6": "RTTY: veel betere decodering",
  "t.1xl4lfazo0t": "Als de frequenties van radio en Aurora verschillen, worden QSO's op de verkeerde band gelogd: controleer ze als je van band wisselt.",
  "t.1xoxysn097e": "Hij zendt maar het vermogen is nul",
  "t.1xrh8431s6z": "Schakel [[ctl.hound]] in: de controle start vanzelf wanneer de code binnenkomt ([[gen2.otpVerify]] staat standaard aan).",
  "t.1xs35cohobi": "[[toast.position]]: [[toast.pos.top]], [[toast.pos.topRight]] of [[toast.pos.bottom]]. [[toast.size]]: [[toast.sz.small]], [[toast.sz.normal]] of [[toast.sz.large]].",
  "t.1xuh47dxbsf": "Als de PTT de radio niet schakelde (de frequentie veranderde maar geen PTT), probeert Aurora het nu toch, ook na een gemiste uitlezing van de radio, en als het niet start verschijnt bovenaan een melding met de reden en een verwijzing naar Instellingen › Radio en “Test PTT”. Het contestmenu staat in elke categorie in volgorde van startdatum, en de “×N” van herhaalde zendingen verschuift de vlag niet meer.",
  "t.1xyqn9z00s2": "Vink in het tabblad Hamlib “Connect to active HAMLIB instance” (127.0.0.1, 4532) en “VFO MODE” aan om beide VFO’s te zien.",
  "t.1y0xe9drskz": "Het paneel toont de stations die CQ roepen en de voor jou nieuwe; [[panel.all]] toont in plaats daarvan alles.",
  "t.1y58codxhjv": "Geluiden",
  "t.1y8dxnpf6a": "De radio verbinden: de checklist",
  "t.1ybodi5214s": "De radio verbinden (CAT)",
  "t.1ybx481h9mo": "PSK31, PSK63 en RTTY op de pagina «PSK · RTTY · SSTV»",
  "t.1ydtzbngrgp": "PSK31 en PSK63: ontvanger vernieuwd",
  "t.1ynjqqvjiph": "De locator wordt gebruikt voor afstanden, de kaart en de stations die jou horen.",
  "t.1ynn900fe9i": "De waterval afstellen",
  "t.1yosswbtubd": "Bij PSK, RTTY en CW gaat de scan van het ene station naar het volgende en bewaren de 20 geheugens je favoriete instellingen. Ze stel je in via [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.digi]] › [[sw.pg.digiScan]].",
  "t.1yrzckfpfeg": "Contesten",
  "t.1yw2xajq1jd": "Boven het vak staat de bedieningsbalk: 12 toetsen per rij (F1-F12), 4 rijen met Ctrl en Shift; het tandwiel toont ze allemaal. Een klik of de toets op het toetsenbord voert de macro uit; rechtsklikken bewerkt hem (toets, label, kleur, tekst, commando’s tussen < >, voor alle modi of alleen de gebruikte). Vul “[[digi.f.call]]”, “[[digi.f.name]]” en “[[digi.f.qth]]” in: de commando’s <CALL>, <NAME>, <QTH> gebruiken ze.",
  "t.1yx1p1ga9wn": "Het logboek meldt “port already in use”: een ander programma gebruikt de poort (JTDX, GridTracker, JTAlert). Sluit het, of gebruik een andere poort of multicast.",
  "t.1yzi6qqfxog": "Rechtsboven: taal, geluidsmeldingen (de luidspreker, met het volume ernaast) en licht of donker thema.",
  "t.1z61kch23ks": "De Fox zijn (pagina Fox)",
  "t.1z7e2f06cq7": "Dubbele QSO’s: het QSO komt via twee wegen binnen. In [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] staan de primaire en secundaire UDP-server van Aurora ook op 127.0.0.1:2237: zet uit wat je niet nodig hebt, of gebruik niet ook de ADIF-bestandsmethode.",
  "t.1zdqvjo2x44": "Een SSTV-zending duurt van een halve minuut tot bijna vijf: houd Pwr laag en stop de FT8-automatisering voordat je zendt. De instellingen staan in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sec.sstv]], ook via het ⚙-wieltje op de pagina.",
  "t.1zim2twmzeg": "[[auto.b5]]: na zoveel minuten zonder CQ die het beantwoorden waard is kan Aurora zelf CQ roepen (alleen in live-modus, met het zenden in rust), of Band Hopping inschakelen om van band te wisselen.",
  "t.1zm3ns05ngn": "Kies in het andere programma Hamlib via het netwerk (NET rigctl), adres 127.0.0.1, poort 4532.",
  "t.1zumwm5gl60": "In de radio: data-audio via USB (bijvoorbeeld DATA MOD USB bij Icom, DATA VOX OFF bij Kenwood).",
  "t.205m6hveyjn": "[[ctl.split]] schakelt split in, [[ctl.clear_dx]] wist het te roepen station.",
  "t.206ei34l6qb": "[[nav.news]]",
  "t.207qkeyjdqt": "Elk geheugen bewaart modus, frequenties, RTTY, AFC, Snap en squelch. Het wordt opgeslagen via het menu [[digi.menu.options]] › [[digi.mi.memory]] › [[digi.mi.memWrite]] van de pagina; bij “[[sw.mem.title]]” zie je het, roep je het op met “[[sw.mem.load]]” of maak je het leeg met “[[sw.mem.clear]]”.",
  "t.209z0b0ni5y": "“[[rep.show]]” en “[[rep.showAuto]]” tonen precies de tekst die zou worden verzonden. Rapporten gaan naar de dienst van de ontwikkelaar van Aurora (op Cloudflare) en worden na 90 dagen gewist; het ID is een willekeurig getal dat je met “[[rep.newId]]” opnieuw kunt maken.",
  "t.20cp0rwn0xq": "Er hoeft niets te worden opgeslagen: elke wijziging wordt na een moment en bij het verlaten van de pagina vanzelf opgeslagen en toegepast.",
  "t.20kddj4t9q": "Gaat in TX maar geen vermogen: dan is het audio (uitgang in [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]], data-audio via USB, niveau).",
  "t.20l43wh1l14": "Zend en let op de ALC van de radio.",
  "t.20odxzo8i6a": "Een pagina van een andere website die in je browser openstaat kan de status van Aurora niet meer lezen en de radio niet meer laten zenden. Split DX klopt altijd met de radio en gaat nooit uit terwijl je zendt. WSPR, FST4W en FST4 komen op de juiste frequentie uit met split Rig of Fake It, en FST4W luistert net als WSJT-X op 1400-1600 Hz. Een bezette COM-poort en OmniRig zijn veiliger, en Cat4OM accepteert een met de hand ingevoerde Control-poort.",
  "t.20pkwpsdcyp": "De richting wordt berekend van jouw locator naar die van het DX-station: beide zijn nodig.",
  "t.20q16eoo4pl": "Aurora zegt TX maar de radio blijft op ontvangen: het is bijna altijd de CAT of de PTT.",
  "t.20uvyygzq45": "Paden worden met “›” geschreven, bijvoorbeeld [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]. eQSL, Wavelog, ClubLog, QRZ.com en LoTW staan in “[[sw.fam.log]] › [[sw.sec.log]]”; GridTracker, Log4OM en N1MM in “[[sw.fam.log]] › [[sw.pg.reporting]]”; spots naar PSK Reporter en DXSummit in “[[sw.fam.log]] › [[tab.online]]”.",
  "t.20uzsoaq7g2": "De RTTY-ontvanger decodeert elk teken als geheel en geeft het de kans dat het juist is: onzekere tekens verschijnen vervaagd. Drie ketens werken samen (gewoon, met begrenzer en met niveaus ten opzichte van de ruis) en voor elk teken wint de zekerste: zo houdt hij fading, flutter en een pompende AGC van de radio uit. Een verloren letters/cijfers-wissel wordt aan het eind van het woord hersteld, en herhaalde woorden (roepnamen, rapporten) worden opgeteld.",
  "t.20vp1pglfk6": "Het RX-venster staat standaard aan, zoals “Rx Frequency” in WSJT-X: het toont berichten rond de RX-frequentie, die aan jou gericht zijn en je eigen zendingen. Zet het uit en weer aan met de RX-knop in de waterval-balk; de keuze wordt onthouden.",
  "t.20yls9a5lmo": "De pagina [[nav.sstv]] ontvangt en verzendt beelden (Martin, Scottie, Robot, PD, Wraase) met dezelfde geluidskaart en PTT als FT8, zonder het te storen.",
  "t.2123icg13hx": "Met TCI (SDR) wordt de Pwr-schuifregelaar niet gebruikt: stel het vermogen in op de SDR, met PWR − / + op het radiodisplay.",
  "t.21bar5xhxz1": "LogHX en GridTracker samen: gebruik in Aurora “+ [[int.p.multicast]]” (239.255.0.1, poort 2237) en zet in LogHX multicast aan met dezelfde groep en poort; of laat LogHX de pakketten opnieuw doorsturen naar het andere programma (rebroadcast).",
  "t.21blg5x59q1": "De tray-agent (naast de klok) gebruikt de in Aurora gekozen taal: de pop-upkaarten volgen die meteen, het tray-menu na een herstart van de agent (bijvoorbeeld bij de volgende Windows-start).",
  "t.21esaya6sz": "Het radiodisplay bovenaan verschijnt niet: zonder CAT zou het niets te tonen hebben. Het komt terug zodra je Hamlib, OmniRig of TCI kiest.",
  "t.21jh5pzljj4": "Vrije tekst langer dan 13 tekens wordt nog steeds op 13 afgekapt.",
  "t.21lx89o54mz": "Het toont de laatste QSO’s: die van Log4OM als Aurora zijn logboek leest, anders het eigen logboek van Aurora, met land en rapporten.",
  "t.21oykaqtnb": "Modusgroepen bovenaan en radio op de frequentie van de modus",
  "t.21sk97fza8c": "STOP TX schakelt de automatisering altijd uit en stopt ook de CQ die het zelf heeft geroepen. De limieten op de pc en het uitschakelen als er geen apparaat is verbonden blijven van kracht. In live-modus zet Aurora [[ctl.enable_tx]] vanzelf aan (zonder dat gaat er geen antwoord uit); wanneer de automatisering stopt, om welke reden ook, gaat [[ctl.enable_tx]] terug naar hoe het was voordat je het aanzette.",
  "t.21uf1d2i1yf": "VFO schakelt naar de andere (A en B, of Main en Sub). RIT en XIT: een klik zet ze op nul.",
  "t.21xhiizrsx7": "Tune direct, Clear Avg voor JT65 en duidelijkere teksten",
  "t.227dtqmxn71": "Het zenden stoppen",
  "t.22e0b32z5ks": "Kies CW in het menu Modus van de pagina [[nav.digi]]: zenden gebruikt een toon met afgeronde flanken op de ingestelde snelheid, bij ontvangst volgt de snelheid vanzelf het station (tussen de helft en het dubbele van de ingestelde).",
  "t.22jbqnf6276": "Volledige herziening en beveiliging: externe websites, Split DX, WSPR en FST4W",
  "t.22lgdc68zg9": "Als je externe logboek al naar een dienst uploadt, zet die dan niet ook in Aurora aan: het QSO zou dubbel aankomen.",
  "t.237o2e61l01": "Dubbele QSO’s: laat hetzelfde QSO niet ook via GridTracker of JTAlert binnenkomen.",
  "t.238rnajf5jo": "Op de pagina [[nav.station]] verschijnt onder de Tx-berichten «Fox verified» in groen of «Fox NOT valid» in rood.",
  "t.23b5c3vq97s": "In het geluidsmenu van elke melding staan, naast de geluiden van Aurora, “Stem” en “[[snd.myFiles]]”.",
  "t.23cvbvmuo7m": "De twee schakelaars bestaan alleen in FT8 en staan in de rij met ontvangstregelingen.",
  "t.23d1nrl16ab": "Kies in [[nav.settings]] › [[sw.sec.station]] › [[tab.audio]] “TCI (dalla radio)” als ingang en “TCI (alla radio)” als uitgang.",
  "t.23el4uxiawd": "Er komt niets aan: een ander programma gebruikt poort 2237 al (JTDX, WSJT-X, GridTracker). Sluit het, of gebruik een andere vrije poort (bijvoorbeeld 2239), zowel in Aurora als op de twee BBLogger-rijen.",
  "t.23g3w7frcxk": "Onderaan de boom staat “[[sw.tab.info]]”: dat is de pagina die je ziet als je Instellingen opent, met het laatste nieuws over Aurora en “[[about.donateTitle]]”.",
  "t.23h5jr6q8hs": "De grote melding voor een nieuw DXCC verschijnt één keer per station; kies in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] “[[not2.popPos]]” en “[[not2.popSound]]”.",
  "t.23nepszvfx4": "De regels verbieden Fox/Hound en multi-streaming: zolang een contest actief is blijven ze uit. Veel contesten eisen ook dat de operator elke QSO start (geen onbemande automatische CQ). Regels veranderen elk jaar: “[[contest.rules]]” toont de controledatum, de te controleren punten en de link naar de officiële regels. Samengestelde roepnamen passen niet in contestberichten (alleen /P en /R): Aurora blijft bij normale berichten.",
  "t.23sksb828q3": "De linkerknop verplaatst de groene balk (Rx), de rechterknop de rode (Tx); Shift + klik verplaatst ook de rode. Houd de knop ingedrukt en de balk volgt de muis. De rode beweegt zelfs terwijl je zendt: de toon verandert meteen. Kies een vrije plek om te zenden.",
  "t.23vatsl8ye7": "OmniRig: Aurora bestuurt het rechtstreeks via COM, zoals WSJT-X, zonder PowerShell. De fout “toegang geweigerd” is verdwenen, het OmniRig-venster springt niet meer op en PTT is sneller. OmniRig moet alleen geïnstalleerd zijn met de radio erin ingesteld.",
  "t.23xmg2eqqh0": "Zet in “[[fox.callers]]” de stations in de wachtrij (ook met een dubbelklik); Aurora zendt het rapport, wacht op R+rapport en sluit af met RR73, ook gecombineerd met het rapport voor de volgende.",
  "t.23zeu7a2qxz": "Met het adres van de helper in “[[sup.email]]” opent “[[sup.sendMail]]” een al ingevulde mail: sleep het zipbestand erin.",
  "t.24cb3uehtgk": "Het openen van de pagina PSK·RTTY·CW of SSTV vanuit FT8 start het luisteren nu altijd opnieuw (#45). Rijen van Fox-stations tonen het hele bericht, de Fox-vlag en het land, en twijfelachtige Fox-berichten gaan door het WSJT-X-filter. De installer is er nu ook in het Nederlands, met de pagina met netwerkgegevens vertaald in zeven talen.",
  "t.24i2e8hwaxe": "Een DXpeditie werken als Hound",
  "t.24o72g76kap": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]] → vak “[[rep.title]]”: zet “[[rep.ask]]” aan en, als je wilt, “[[rep.auto]]”. Om ze uit te zetten, haal je het vinkje weg: er wordt niets meer verzonden en de wachtrij wordt geleegd.",
  "t.24pqb3n8q72": "[[cmd.tune]] en [[cmd.logQso]] verschijnen als je ze aanzet in Instellingen › Modi › FT8 · FT4 › Berichten en filters: Tune zendt een draaggolf om af te stemmen (rood tijdens het zenden), Log QSO legt het lopende QSO met de hand vast. Tune start meteen, ook midden in een lange periode (FST4, FST4W, WSPR), en duurt hoogstens 2 minuten.",
  "t.24uwtfqkts3": "Wat de waterval en de Rx- en Tx-balken tonen.",
  "t.254y02fzch8": "Dubbele QSO’s: het QSO komt op twee manieren binnen. In [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] staan de primaire en secundaire UDP-server van Aurora ook op 127.0.0.1:2237: zet uit wat je niet nodig hebt, of verwijder de LogHX-bestemming en houd de primaire server.",
  "t.25crq7s5inx": "Test: maak een QSO met Aurora (of voeg er met de hand een toe vanaf de Logboek-pagina): het moet in BBLogger verschijnen.",
  "t.25jf1lw7w2s": "Wie LoTW gebruikt",
  "t.25lzwi0iowk": "Slechts één programma kan op een unicastpoort luisteren. Twee programma’s: elk één bestemming met verschillende poorten, of multicast als beide daarnaar kunnen luisteren.",
  "t.25my4rmsgi3": "Gebruik één methode tegelijk (netwerk of bestand), anders komen QSO’s dubbel binnen.",
  "t.25scbtkflcb": "Weet je poort en snelheid niet? Probeer “[[cat.detect]]”: het vindt ze voor je.",
  "t.25whsahqizm": "Open in BBLogger “Nuovo QSO” (Nieuw QSO) of “Fast QSO” en druk op het tandwielpictogram naast “Auto-Save”: “Configurazione interfaccia Wsjtx” opent.",
  "t.25xeofr566x": "Scan de QR-code met de cameraapp van de telefoon: Aurora opent en het koppelen wordt vanzelf voltooid. Zonder camera open je de getoonde link en voer je de code in.",
  "t.25ycs8nulrz": "[[nav.settings]] › [[sw.sec.station]] › [[tab.audio]]: de uitgang moet de kaart van de radio zijn (vaak “USB Audio CODEC”).",
  "t.261hi75sqgh": "Open de pagina [[nav.rotator]]: de doorgetrokken naald is de antenne, de gestippelde het doel; de groene markering is het DX-station (korte weg), de oranje de lange weg.",
  "t.262541qcmzv": "Op de pagina begint elk QSO geselecteerd: filter op roepnaam, datums, band en modus, en vink de gewenste rijen uit of aan.",
  "t.262ajet4le7": "Het paneel [[panel.log]]",
  "t.265lo2epe9t": "Laat Aurora werken: als de Fox je een rapport geeft, zendt het R+rapport, en als zijn RR73 binnenkomt wordt de QSO gelogd.",
  "t.266jitm6su3": "[[set.back]] brengt je terug naar de hoofdpagina.",
  "t.26aqds6ogyf": "Op de hoofdpagina hoort de Rx-balk “Goed” te zeggen. Staat er Laag of Overstuurd, verschuif dan de Rx-schuifregelaar (of laat AUTO aan).",
  "t.26bxr500q8": "Met de squelch aan wordt alleen afgedrukt als de laatste tekens waarschijnlijk zijn: geen verzonnen tekens op ruis, ook bij zeer zwakke signalen. De S/R-drempel uit de instellingen komt er alleen bij als je hem boven 0 dB zet.",
  "t.26e2axizetj": "Als alternatief voor het netwerk leest BBLogger het bestand dat Aurora bij elk QSO schrijft, aurora_log.adi. Het QSO bereikt BBLogger wanneer Aurora het logt: het is de veiligste manier, maar het toont het QSO niet terwijl het bezig is.",
  "t.26gw81yrnaw": "Je keuzes worden vanzelf opgeslagen ([[cat.apply]] laat ze meteen ingaan). Druk in het vak “[[cat.grp.test]]” op [[cat.connect]]: de status moet “Verbonden” worden en de frequentie van de radio verschijnt.",
  "t.26opqm6dov2": "RTTY: betere ontvanger en nieuwe instellingen",
  "t.26rfvjjw01o": "Wordt een DXpeditie gespot met “UP 5” in de opmerking, dan zet een dubbelklik (of een enkele klik, als je op de pagina’s PSK, RTTY en CW “[[cop.single]]” hebt gekozen) op de spot de radio op ontvangst op de spotfrequentie en op zenden 5 kHz hoger, op de tweede VFO (echte split). Werkt in de DX-cluster van de pagina Station en van de pagina PSK · RTTY · CW.",
  "t.26vb5wjjhcp": "Zonder CAT: de band met de hand kiezen",
  "t.26vylg8smn4": "Controleer “[[contest.settings]]”: vaste exchange (Field Day “1D DX”), eerste serienummer, categorie, vermogen, Cabrillo-gegevens; kies voor contesten zonder vaste kalender begin en einde. De frequenties van de regels brengen de radio met één klik op de juiste frequentie.",
  "t.2717znd4y1l": "Laat [[ctl.auto_tx]] aan staan.",
  "t.27eqtyfroi9": "Rechtsklik nogmaals op de rij: het station verlaat de wachtrij.",
  "t.27vxq9vlrjk": "FT8: het signaal op de Rx-frequentie wordt eerst geprobeerd, OSD-diepte 4 voor QSO-antwoorden en de gemiddelde DT wordt gevolgd (hoge DT gaat niet meer verloren); a priori-decodering ook voor /P en samengestelde roepnamen. FT4: geen extra filters ten opzichte van WSJT-X, dezelfde kandidatenzoektocht en een tijdslimiet van 5 s. Q65: middeling gebruikt de QSO-lijst, drift wordt gecorrigeerd en de lijst herkent /P en /R. JT65 en JT9: drempels van WSJT-X, Rx-venster eerst geprobeerd en a priori-decodering voor JT65. MSK144: de pingontvanger van WSJT-X, Rx-frequentie en tolerantie in plaats van een vaste 1500 Hz, korte berichten ook in SWL.",
  "t.27yl42huy5k": "Open [[nav.settings]] › [[sw.sec.look]] › [[tab.waterfall]].",
  "t.2851rho2bp2": "Updates",
  "t.28arann7ke6": "Nieuwe staat (VS)",
  "t.28fis2inowz": "Voor DXpedities: in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] staat “[[onl.dxped]]” standaard aan (hier uit te schakelen). De kalender komt van NG3K.",
  "t.28fu5c3s6gd": "Een nieuwe pagina ontvangt en zendt PSK31, PSK63 en RTTY met dezelfde geluidskaart en PTT als FT8: menu’s, een balk met 48 macro’s, een zijlogboek, een waterval met de RX- en TX-driehoekparen en IARU-bandplanfrequenties in de bandkeuze. In het tabblad DX Cluster stemt een klik op een spot de radio af op het signaal en de knop «DX Spot» stuurt de spot naar DXSummit. Het luisteren start vanzelf als je de pagina opent.",
  "t.28leoc269th": "[[ctl.mtd]] (standaard aan) gebruikt alle processors van de pc: het decoderen is eerder klaar als de band druk is, met dezelfde resultaten.",
  "t.28lg1d7bnks": "Blauwe stip met een cijfer: station in de wachtrij, het cijfer is zijn positie.",
  "t.28q11y4ob4j": "Standaard gaan de primaire en de secundaire server allebei naar 127.0.0.1:2237: laat alleen aan wat je logboek nodig heeft, of geef de andere een andere poort.",
  "t.29106by5070": "Wait and Call: met de DX ingesteld en [[ctl.autoseq]] aan, schakel je [[ctl.wait_call]] in. Wanneer de DX CQ roept of zijn QSO beëindigt (RR73, RRR, 73) roept Aurora hem vanzelf, tot ongeveer drie keer.",
  "t.2962ypc64ar": "Open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], vak [[gen2.bandHop]].",
  "t.296j581dkql": "De tekst wordt bepaald door een probabilistische decoder: die houdt de meest waarschijnlijke lezingen open (snelheid van 5 tot 60 WPM, seinstijl, woorden van het CW-verkeer) en kiest zodra hij nog twee tekens heeft gehoord; hij kan veel zwakkere signalen en de handseinsleutel aan. Een noise blanker haalt ontladingen weg vóór het filter. De filterbandbreedte is direct te wijzigen in het menu Modus of in de keuzelijst onderaan, ook breed (1000 Hz) voor een overzicht.",
  "t.296k9r2p06v": "[[nav.settings]] › [[sw.sec.station]] › [[tab.audio]]: uitgang en ingang op de geluidskaart van de radio (recente Icom, Yaesu en Kenwood: “USB Audio CODEC”).",
  "t.298cyxf5i80": "De kolom Modus komt uit het commentaar van de spot (“FT8 -10 dB”, “CW 22 wpm”, “VarAC VARA”). Staat het niet in het commentaar, dan kijkt Aurora naar de frequentie: dicht bij de werkfrequenties van FT8, FT4, JS8, WSPR en PSK31 toont het die modus; anders volgt het het bandplan van IARU Regio 1, CW in de delen alleen voor CW en SSB in de fonie-delen (FM boven 29,52 MHz). In gemengde delen (digitaal en CW, bakens, satellieten) en als het commentaar alleen “Digi” zegt, blijft de kolom leeg, om niet te gokken.",
  "t.29c31girjrp": "Stations in de lucht op de wereldkaart, gekleurd zoals in Bandactiviteit: ze vervagen met de tijd en een boogvormige lijn verbindt ze met jou. Achtergrond, helderheid, greyline, gewerkte (geel) en bevestigde (groen) vierkanten per band en modus staan in de balk; ⚙ opent de rest (automatische nachtkaart, schemering, Maan). Klik op een punt: vierkant, afstand, land en zones. «Propagation» toont de heatmap van wie jou ontving (PSK Reporter), met Spot RX, maximale leeftijd en een lijn van jouw station naar elk ander; «Who calls whom» trekt een stippellijn tussen de twee stations van elke oproep (kleuren, breedte en snelheid in het menu ⚙); vierkanten in de lucht zijn QSX, CQ, CQDX of QRZ, zoals de legenda linksonder zegt.",
  "t.29dpsfbrs0h": "Leeftijd van berichten en nieuwe berichten onderaan",
  "t.29gm646lvp0": "Aurora draait de antenne met rotctld van Hamlib (dezelfde Hamlib als voor CAT): naar het DX-station, de lange weg, of waar je ook klikt.",
  "t.29j8jsrkd5a": "UltraFOX",
  "t.29k7q3taryr": "Wat nooit wordt verzonden: roepnaam, locator, gedecodeerde berichten, QSO-logboek, ALL.TXT, instellingen, wachtwoorden en sleutels, IP-adressen, e-mailadressen, je Windows-gebruikersnaam en de minidumps (die bevatten het geheugen van het programma).",
  "t.29m0f0lipne": "“Stem” spreekt de melding en de roepnaam uit in het fonetisch alfabet (bijv. “Nieuw DXCC! Zulu Six Two November Sierra”). Werkt zonder internet.",
  "t.29uml83vhoy": "In het paneel [[panel.tx]] toont “[[tx.queue]]” onder de DX de wachtende stations met hun nummer. Ze worden na elkaar geroepen zodra de huidige QSO is gelogd.",
  "t.2a6dqlxhw35": "DX Cluster met verplaatsbare kolommen, handigere klok en meldingen",
  "t.2agmwjdl4zt": "Kies met de rechterknop een vrije plek in de waterval (rode balk).",
  "t.2ahk19xvg8w": "[[fil.worked]]; met “[[fil.workedAll]]” verdwijnen ook hun uitwisselingen met andere stations.",
  "t.2apjiphfq94": "Schakel in het SDR-programma de TCI-server in (meestal poort 40001) en de I/Q-stream op 96 kHz; stem de SDR af op het midden van het stuk waarnaar je wilt luisteren (bijv. 144,100 MHz).",
  "t.2atjts16i4z": "Pwr is het Windows-volume van de audio-uitgang naar de radio: 100% op de schuifregelaar = 100% in de Windows-mixer. Aurora zet het vóór elke zending weer gelijk.",
  "t.2av7dzvquyq": "Gebruik de Fox-modus alleen als je echt de expeditie bent en kondig het aan: op de normale band veroorzaakt het storing.",
  "t.2avj9iu7hr9": "Voer gebruiker, wachtwoord of sleutel in: ze worden opgeslagen als je het veld verlaat en de test van het vak start vanzelf.",
  "t.2ax8vhu27qy": "AGC: auto, snel, middel, langzaam, uit, en dan weer van voren af aan.",
  "t.2axxq6uinl": "Eén radio, meerdere programma's",
  "t.2az1wgebqdk": "De pagina «SSTV» ontvangt en zendt Martin, Scottie, Robot, PD en Wraase SC2-180 met dezelfde geluidskaart en PTT als FT8. Bij ontvangst wordt de modus herkend aan de VIS en vult het beeld zich regel voor regel; voor het zenden is er een samensteller met foto’s, tekst, vormen en sjablonen met roepnaam en rapport. Tijdens het zenden toont een rode lijn tot welke regel je bent gekomen en na afloop keert het vanzelf terug naar ontvangen.",
  "t.2b24nd8nolq": "Instellingen heeft veel pagina’s, verdeeld in families. Bovenaan staat het vak “[[sw.search]]”: typ een woord van de optie (accenten maken niet uit) en de lijst met gevonden opties uit alle pagina’s verschijnt.",
  "t.2b94upr6wkv": "Een “*” is een teken dat morse niet kent: zie je er veel, controleer dan of de toon binnen de filterbandbreedte ligt of zet de AFC aan.",
  "t.2bdl46jl2g8": "Wait and Reply en [[ctl.wait_call]]",
  "t.2bq4an6ime0": "[[cmd.report]]: de dB die je verzendt. Aurora stelt ze in op basis van het ontvangen signaal; met de hand gewijzigd gelden ze meteen.",
  "t.2bujz0z2fyg": "Na de QSO start CQ alleen vanzelf opnieuw als [[ctl.auto_tx]] aan staat.",
  "t.2bxlh7u6234": "Controleer de “Zendbeveiligingen”: een actieve beveiliging kan Tx blokkeren.",
  "t.2by5qke05rg": "Stations die je op PSK Reporter horen verschijnen binnen seconden in plaats van minuten op de DX-kaart: Aurora luistert naar de real-time feed (dezelfde die GridTracker gebruikt) en de kaarten verversen elke 10 seconden. Met OmniRig is de verbinding niet meer wisselvallig en het kleine venster blijft niet meer opduiken; frequentiewijzigingen gebruiken ook radio 2. Een geluidskaart die bij het opstarten ontbreekt (radio uit) wordt niet meer als fout gemeld, audio-opname kan beter tegen een drukke pc en een trage vensterstart wordt niet meer voor een vastloper aangezien.",
  "t.2cc3cerk1m6": "Om een modus te forceren kies je die en druk je op “[[sstv.rx.force]]”. Voltooide beelden komen in “[[sstv.hist.received]]”, in de kolom rechts (onderaan de pagina bij smalle vensters en op de telefoon); klik er een aan om het te vergroten, van ruis te ontdoen, op te slaan of te antwoorden.",
  "t.2cuwemslunb": "Aurora probeert ook de berichten die het verwacht: zo leest het zwakkere signalen dan gebruikelijk.",
  "t.2cw6em54wa2": "Zodra het is afgegaan, schakelt [[ctl.wait_call]] uit: schakel het opnieuw in om opnieuw te wachten.",
  "t.2cxhbcch408": "Laad de pagina opnieuw in de browser van de telefoon.",
  "t.2d0mswp5ay0": "Verschijnt de waarschuwing “De pc heeft moeite om op tijd te decoderen”, druk dan op “[[diag.slow_pc.to2]]”: de decodeerdiepte gaat naar Normaal (je kunt hem ook wijzigen in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[fil.decode]] › “[[dec.depth]]”). Komt de waarschuwing terug, dan “[[diag.slow_pc.to1]]”. Aurora wijzigt hem nooit zelf. Ook helpen: Multithread aan, SWL en a7/a8 uit en zware programma’s gesloten (browser met veel tabbladen, games, videogesprekken).",
  "t.2d3zxdlh24j": "Modus MSK144 (meteorscatter)",
  "t.2d62y3ela4x": "Wanneer het decoderen start en Full duplex",
  "t.2d7e7t4wnc1": "Bij FT8- en FT4-spots wordt Split DX niet gebruikt: DXpedities werken met Fox/Hound en Aurora regelt de split van de radio via Instellingen › Station › Radio. Met de schakelaar uit stemt de spot alleen af en is het label “UP 5” slechts informatie.",
  "t.2d8zs8zaaep": "PSK Reporter in real time, stabiele OmniRig, rustiger opstarten en audio",
  "t.2del8sdimr3": "Kies in het logboekpaneel “Kaart”: stations die hun locator zenden verschijnen met hun roepnaam, in de kleur van wat nieuw is (dezelfde als bij Bandactiviteit); CQ-roepers hebben een kader.",
  "t.2dfcj401ku3": "Naar een station in de wachtrij springen",
  "t.2dg458a4wkn": "In het paneel [[panel.tx]], rechtsboven naast de DX, toont het label RX (groen) zolang je luistert; tijdens het zenden wordt het de rode knop “[[stop.button]] (Esc)”.",
  "t.2dnhupy2umv": "Log gesloten: de QSO’s komen later aan",
  "t.2dqac6b8dvi": "Zet in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]] “[[not2.unconfirmed]]” aan (en “[[not2.unconfirmedGrid]]” voor locatorvelden): een land dat is gewerkt maar niet bevestigd (LoTW of QSL in het logboek) blijft “nieuw DXCC” in de kleuren, het filter van Bandactiviteit en Automatisering. Op de DX-kaart zijn bevestigde vierkanten groen, alleen gewerkte geel.",
  "t.2dr9kuuacvp": "Kies boven de lijst met decodes de “[[contest.order]]”: “[[contest.order.value]]” toont alleen de laatste twee periodes, zodat stations die niet meer worden gehoord niet bovenaan blijven staan; “[[contest.order.time]]” toont ze allemaal in tijdsvolgorde, nieuwste onderaan zoals Bandactiviteit, en de lijst volgt vanzelf tot je omhoog scrolt om te lezen. De keuze wordt onthouden.",
  "t.2dra90twxoa": "“[[snd.addFile]]” laadt je eigen geluid (tot 5 MB): het blijft in de lijst staan voor elke melding; met × verwijder je het.",
  "t.2drhtr4tog6": "Schakel bij een full-duplex satellietrig [[gen2.fullDuplex]] in: je ziet dan ook je eigen downlink. Uit wordt de periode waarin je zendt niet gedecodeerd.",
  "t.2dtkfixnzrn": "[[ctl.ap_list]] (standaard aan): “a8” zoekt bij de Rx-balk naar de antwoorden van je partner, als DX Call en DX Grid zijn ingevuld; “a7” zoekt naar de volgende berichten van de QSO’s die in de vorige periode zijn gehoord.",
  "t.2e0t0i7wr2n": "Houd de muis boven het “?” naast een onderdeel om te lezen wat het doet; een klik houdt de uitleg open.",
  "t.2e1eq1gw5ix": "Er komt niets aan: adres en poort moeten in beide programma’s overeenkomen en het luisteren moet in het logboek gestart zijn.",
  "t.2e2pbeuneo7": "Maak je QSO’s ook met het log gesloten: Aurora zet ze in de wachtrij.",
  "t.2e8lx2ahqoo": "Aurora kan vanzelf door meerdere banden of frequenties roteren, één elke twee minuten, om te luisteren waar activiteit is.",
  "t.2ecv9zw37wf": "Stel voor RTTY shift en snelheid in zoals het station dat je ontvangt (meestal 170 Hz en 45,45 baud); „[[digi.freq.rx]]” is het midden tussen de twee tonen (in USB is de mark de hoge toon). De macro’s wijzig je in „[[digi.macros.edit]]”.",
  "t.2edi99hgbvm": "Kies in MSK144 naast de modus de T/R-periode (5, 10, 15 of 30 s, zoals WSJT-X): die wordt per band onthouden, standaard 15 s op 6 m en 4 m en 30 s op 2 m en de andere banden. De knop “Sh” schakelt korte berichten in: R+rapport, RRR en 73 gaan uit als “<DX MY> R+03” (rapport afgerond op -03, +00, +03, +06, +10, +13, +16) en de naar jou gezonden worden gedecodeerd. “Sh” en SWL sluiten elkaar uit. Je partner moet dezelfde periode gebruiken en “Sh” aan hebben.",
  "t.2ei8shrmg6s": "BBLogger (gratis Italiaans logprogramma, site aribusto.it, nu ontwikkeld door IZ2BKT) ontvangt de QSO’s van Aurora zoals die van WSJT-X en JTDX. Er zijn twee dingen nodig: een bestemming in Aurora en de “Wsjtx interface” in BBLogger, met hetzelfde adres en dezelfde poort.",
  "t.2eqcnflmxgj": "Stem en eigen bestanden voor meldingen",
  "t.2ew9w3aqrj3": "Bovenaan de pagina met geluiden staat “[[snd.voiceLang]]”: de taal van Aurora of altijd Engels.",
  "t.2ewj97dsxt6": "Berichten die niet verzonden kunnen worden: als een roepnaam of bericht anders zou aankomen dan het is geschreven, gaat het niet de lucht in en wordt de reeks uitgeschakeld.",
  "t.2f1kgdymfwv": "De afstandsbediening",
  "t.2faee9b8mf7": "Satellieten: kaart, doorgangen, Doppler op de radio en rotor",
  "t.2fco4n32ksg": "Nieuwe berichten onderaan: druk in de titelbalk van Bandactiviteit en van het RX-venster op “[[list.bottom.off]]”. Dit wordt “[[list.bottom.on]]”: het nieuwste bericht is steeds de laatste regel en de lijst schuift omhoog. Elke lijst heeft zijn eigen keuze; die staat ook in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]], “[[list.bottom]]”.",
  "t.2fkwan48q8h": "Open in LogHX de instelling van het digitale programma: Ctrl + klik op het JTDX-pictogram (of WSJT-X) in het hoofdvenster, of via het menu Setup. Aurora stelt zich voor als JTDX: gebruik de JTDX-instelling.",
  "t.2fqm22rs92q": "Schakel [[gen2.bandHopOn]] in en sla op: bij de volgende even minuut gaat de rig naar het eerste item.",
  "t.2fsww6z0z6t": "Het paneel Opdrachten",
  "t.2fwgemddu2f": "Op Linux wordt eerst de Hamlib van het systeem geprobeerd, dezelfde als WSJT-X gebruikt (#41), en de ALSA-waarschuwing «snd_pcm_avail_delay» stopt het zenden niet meer. TCI: het sluiten van ExpertSDR of Thetis stuurt geen foutrapporten meer en Windows-fout 997 verbreekt de verbinding niet meer. «Clear» stuurt ook Clear naar GridTracker en JTAlert. Wavelog v2: de stationlijst kan nu worden gelezen. PSK Reporter: spots in de wachtrij worden verzonden als Aurora sluit.",
  "t.2g07hbfzsh": "Met het middelen van perioden aan wordt een signaal dat voor één periode te zwak is opgeteld bij de vorige perioden met dezelfde pariteit (zelfde frequentie binnen F Tol, zelfde DT binnen 0,2 s, tot 64 perioden) en draagt het bericht uit het gemiddelde het merk van a-priori-berichten. “Clear Avg” maakt het gemiddelde leeg; het leegt zichzelf ook bij wisselen van modus, submodus of frequentie, en met “Auto Clear Avg” na een bericht uit het gemiddelde dicht bij de Rx-frequentie. Dezelfde reset is de knop ⟲ “Clear Avg” naast AP en Prof.: druk erop als je opnieuw wilt beginnen.",
  "t.2g5c1977d4w": "Kenwood TS-590SG, TS-890S: virtuele COM-poort via USB. Kies bij [[cat.rig]] het model; [[cat.baud]] gelijk aan die in het radiomenu (zie de handleiding).",
  "t.2g5jahz4tfa": "De radio: LogHX en Aurora kunnen niet dezelfde COM-poort openen. Moet LogHX de frequentie lezen, gebruik dan OmniRig in beide (in Aurora [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] › OmniRig), of laat CAT in LogHX uit.",
  "t.2ta08in5ls": "“ADIF opslaan…” opent het Windows-venster om map en naam te kiezen: het bestand bevat alleen de geselecteerde QSO’s. Op de telefoon downloadt de knop het bestand.",
  "t.34r3o4v678": "Leeftijd van berichten: open [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]] en vink in het vak “[[fil.grp.both]]” “[[gen.showAge]]” aan. De eerste kolom geeft aan hoe lang geleden het bericht binnenkwam (45 s, 3 min) en werkt zichzelf bij; houd de muis boven het getal om de UTC-tijd te zien.",
  "t.39j8oqw3rh": "Aan de slag",
  "t.3elxiv4637": "Open [[nav.settings]] › [[sw.fam.log]] › [[sw.sec.log]] en zet de dienst aan.",
  "t.3gnbswe959": "Hoge SWR: als de radio tijdens het zenden een SWR boven de limiet meet, stopt Aurora meteen. De limiet staat in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]] (standaard 2,5, 0 = nooit).",
  "t.3gp6y8tgnj": "Aurora bevat een wereldkaart, “Aurora-kaart” (land en grenzen onder dag en nacht, sporen en voetafdrukken): dit is de basiskaart als “Contour HiRes” ontbreekt. De afbeeldingen die je toevoegt met “[[sat.map.add]]” (equirectangulair 360° × 180°, in de map “maps” van de Aurora-gegevens) blijven altijd te kiezen in de keuzelijst “[[sat.map.pick]]” en in de instellingen van de pagina, waar ook “[[sat.set.mapAuto]]” staat. Controleer de satellietfrequenties bij AMSAT; schrijf het bestand satelliti-utente.json om meer satellieten toe te voegen.",
  "t.3n412xlbtn": "In FT8 moet de pc-tijd binnen een fractie van een seconde kloppen. Als alles goed is zie je niets; anders verschijnt bovenaan een gele waarschuwing.",
  "t.3uyf7e9dbu": "Open [[nav.settings]] › [[sw.sec.station]] › [[sw.tab.rotator]] en kies “[[rot.set.connection]]”: “[[rot.set.launch]]” als de rotor op deze computer is aangesloten, “[[rot.set.remote]]” als rotctld al draait (ook op een andere computer, poort 4533).",
  "t.3x3c6dfgk3": "Decoders afgestemd op WSJT-X 3.3: FT8, FT4, Q65, JT65, JT9 en MSK144",
  "t.3xcyd59sjx": "Stond de radio uit of de USB-kabel los toen Aurora startte? Opnieuw starten is niet nodig: zet de radio aan (of steek de kabel weer in) en het zenden herstelt zich vanzelf op dezelfde geluidskaart.",
  "t.41aaxkfknq": "Muiswiel of de kleine knoppen + en − om te zoomen; indrukken en slepen om te verschuiven.",
  "t.43lgi9fivi": "Pagina niet gevonden? Typ in het zoekvak bovenaan de boom: alleen de pagina’s die erover gaan blijven over, en een klik brengt je naar het juiste pad. Het zoekvak vindt ook losse instellingen.",
  "t.46p77ysual": "Eén klik op “[[stop.button]] (Esc)” stopt het zenden meteen en het label gaat terug naar RX. De Esc-toets stopt het ook en schakelt [[ctl.enable_tx]] uit, als “[[gen.escStop]]” aan staat in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.pg.messages]].",
  "t.47ltj8m9w8": "Kies in Instellingen › Station › Radio, onder «Besturingssysteem», «Geen (geen CAT, met de hand afstemmen)».",
  "t.4fgpud534t": "[[wfs.bpp]] (fabriek 5) en [[wfs.start]]: hoeveel detail en waar de waterval begint. [[wfs.navg]]: hoger maakt de waterval trager en minder ruizig.",
  "t.4gw8f3x40x": "[[sup.privacy]]",
  "t.4lot4bn2bh": "Zet [[ctl.filter]] uit: als het aan staat decodeert het alleen van 60 Hz onder tot 110 Hz boven Rx. Als het aan staat is de waterval aan de zijkanten donker.",
  "t.4lxg5dg113": "Op een smal scherm wordt de pagina Station een compacte afstandsbediening.",
  "t.4ni331k4ay": "Met een SDR die TCI heeft (SunSDR met ExpertSDR, ANAN met Thetis) is één verbinding genoeg: commando's en audio lopen via TCI, zonder virtuele audiokabels.",
  "t.4s2dvaanb9": "Cat4OM compleet: kies de radio en netwerkaudio",
  "t.4slj7qmi37": "Via UDP gaat een QSO naar een gesloten log verloren: er is geen bevestiging. Met “[[int.resend]]” kijkt Aurora of het log op deze pc open is; is het gesloten, dan houdt Aurora de QSO apart en stuurt die zelf zodra het log weer open is. Geldt voor alle logs die “[[int.adif]]” of “[[int.n1mm]]” ontvangen: Log4OM, HRD Logbook, WaveLogGate en de andere.",
  "t.4t665ep3ah": "Rx-venster aan, «Spot DX» in Station en Rig/Fake It split",
  "t.4tf523r1oa": "Geen spots in het clusterpaneel.",
  "t.4vsfmv4swt": "Eén knop verzamelt logboeken, crashrapporten en instellingen in een zipbestand op het Bureaublad, zonder wachtwoorden.",
  "t.544duftynr": "De bovenbalk groepeert nu de modi (FT8, VHF, één knop «PSK · RTTY · SSTV», Satellieten) en heeft rechts de pagina’s Logboek, DX-kaart, Propagatie en Rotor. Als je van modus wisselt, gaat de radio naar de juiste frequentie: van FT8 naar MSK144 op 40 m gaat naar de eerste band waar de modus bestaat (6 m, op de frequentie van de IARU-regio die je hebt ingesteld: 50,380 MHz in Europa). De bandkeuzes van de tekstmodi en SSTV gebruiken de IARU-bandplanfrequenties voor jouw regio.",
  "t.59s1oakaaf": "Druk op “Start UDP”: standaard luistert de server op 127.0.0.1, poort 50001.",
  "t.5bjbtfy6hk": "Voeg teksten en vormen toe (“[[sstv.add.text]]”) of een sjabloon uit “[[sstv.tpl.title]]”: {MYCALL}, {CALL}, {RST}, {GRID}, {DATE} worden vanzelf ingevuld. Elke laag verplaatst, schaalt en draait met zijn handvatten.",
  "t.5daziufif6": "Het tabblad “Kaart” van het logboekpaneel volgt altijd de gebruikte band en heeft één rij met bedieningselementen: Lijnen, Wie roept wie, Alleen wie mij hoort, Roepnamen. Al het andere stel je in op de DX-kaartpagina. Als een QSO wordt gelogd, schakelt het paneel vanzelf naar het Logboek (of Intern logboek), toont de nieuwe rij en gaat terug naar de Kaart.",
  "t.5m3sdjc0r": "Q65-30A kies je in de modusschakelaar: periodes van 30 s (even en oneven), berichten in FT8-stijl (ook RR73), 65 tonen over ongeveer 217 Hz. Het is gevoeliger dan FT8 en geschikt voor 6 m en 2 m: de frequenties zijn 50,275 en 144,180 MHz, met de EME-frequenties in de frequentielijst.",
  "t.5y8wwgd4me": "Deze gegevens komen alleen binnen met “[[cat.extras]]” aan (met Hamlib). Staat het uit, dan zegt het uitgebreide display dat.",
  "t.61wrjax8vy": "Je roepnaam en locator ([[nav.settings]] › [[sw.sec.station]] › [[sw.pg.personal]]) en de radiofrequentie via CAT zijn nodig. Het lampje in het vak toont hoe de laatste verzending ging; antwoordt WSPRnet niet, dan wordt het hoogstens een uur opnieuw geprobeerd. De pagina toont ook hoeveel verzendingen nog wachten, inclusief de lopende.",
  "t.658fqstg8w": "Om terug te gaan, of op een andere pc: “[[bak.restore]]”, kies het zipbestand, sluit dan Aurora af via het systeemvak en open het opnieuw.",
  "t.6839g5vffi": "[[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]] → “[[int.title]]”: voeg de bestemming van het log toe of open die, met adres 127.0.0.1 en de poort waarop het log luistert.",
  "t.6eh9mk1rf1": "Als “[[not2.unconfirmed]]” (of “[[not2.unconfirmedGrid]]”) aan staat, hebben in de lijst Bandactiviteit de rijen die alleen nieuw zijn omdat ze niet bevestigd zijn dezelfde kleur als de nieuwe, maar lichter en gestreept; echt nieuwe blijven egaal gekleurd. Het voorbeeld in [[nav.settings]] › [[sw.sec.look]] › [[sw.tab.colors]] toont het verschil.",
  "t.6gubpzi4od": "Updates zonder haperingen en WebView2",
  "t.6ic5d7r7k2": "Slechts één venster wissen: druk in de titelbalk van Bandactiviteit en van het RX-venster op “[[list.clear]]”. Dit wist alleen dat venster, nieuwe berichten verschijnen weer.",
  "t.6tqy24ukgf": "DX-kaart: band, lijnen en roepnamen",
  "t.6xsuwobnk6": "Split DX vanuit de cluster, Cat4OM automatisch, Nederlands en FST4W-baken met WSPRnet",
  "t.75rxy2xre8": "Beelden in SSTV",
  "t.77lakfdx0x": "Wat wordt verzonden: versie van Aurora en Windows, engine, radiomodel, PTT, CAT-backend, naam van de geluidskaart, probleemgebied, opgeschoonde foutmelding en hoe vaak het gebeurde; na een crash ook het opgeschoonde logboek en de crashtekstrapporten.",
  "t.78x1ik4zg6": "De DX Cluster is leeg",
  "t.7husjuoul4": "Icom: 115200, PTT CAT, CI-V 0; in de radio CI-V USB Port “Unlink from [REMOTE]”, Echo Back OFF, DATA MOD USB. Yaesu: 38400, CAT RTS OFF. Kenwood: 115200, DATA VOX OFF.",
  "t.7noy6nyclb": "Aurora installeren",
  "t.7q1u47oqs4": "Laat Aurora de radio besturen: frequentie, mode en zenden.",
  "t.82rtrixm2i": "De knop RX/TX (of de toets Pause) opent de uitzending en houdt die aan: zonder tekst stuurt RTTY het wachtsignaal. Wat je in het zendvenster typt, gaat de lucht in terwijl je typt; druk opnieuw op RX/TX of Pause en zodra de al getypte tekst verzonden is, ga je terug naar ontvangst. Esc stopt meteen.",
  "t.893l0gpyf5": "Typ in het vak “[[fil.highlight]]” roepnamen, prefixen of landen: hun rijen worden paars. “[[fil.bypass]]” toont een tijdje alles zonder de filters kwijt te raken.",
  "t.896m0apzu5": "PTT: melding met de reden en geen verwerping, contests in datumvolgorde",
  "t.8iair2nbfn": "[[panel.cq]] en DXpedities",
  "t.8nx29ewr2p": "“[[rep.sendBundle]]” uploadt het pakket zonder persoonlijke gegevens en toont een code: geef die door aan wie je helpt, zodat die het kan terugvinden.",
  "t.8z5e2e46b0": "Mark en space waren verwisseld: nu is de frequentie het midden tussen de twee tonen en is in USB de mark de hoge toon. Er is een knop «Rev» en met de radio in LSB is de omkering automatisch. Shift, snelheid en Rev kunnen ook in de onderste balk worden gekozen, en de squelch drukt geen ruis meer af.",
  "t.93o8nisihm": "BBLogger: QSO’s uit het ADIF-bestand van Aurora",
  "t.93swe6ydkk": "Zet “[[rot.set.enabled]]” aan: de status wordt “[[rot.state.connected]]” en Aurora blijft ook bij de volgende starts verbonden.",
  "t.94qchg6es7": "Al je QSO’s, doorzoekbaar op roepnaam, data, band en modus: kies degene die je wilt en sla ze op in een ADIF-bestand met “Save ADIF…”.",
  "t.966x7gmii": "De CW-ontvanger heeft een filter met een in het menu Modus gekozen bandbreedte (50 tot 500 Hz), een betrouwbaardere snelheidsschatting, procedureteken zoals AR, BT, KN en SK, en een squelch op basis van de signaal-ruisverhouding: op alleen ruis worden geen verzonnen tekens meer afgedrukt. De AFC, die vroeger niets deed, vergrendelt nu op een station dat tot ±100 Hz verschoven is en volgt langzame drift.",
  "t.9aem6g1d7c": "“[[rep.active]]”: [[rep.activeTip]]",
  "t.9c02ucdo2": "In de modipagina’s van [[nav.settings]] › [[sw.fam.modes]] ([[sw.sub.ft8]] › [[fil.decode]], [[sw.sub.jt]], [[sw.sub.vhf]]) vind je de decoderopties van WSJT-X, met zijn fabriekswaarden: diepte (Fast, Normal, Deep), enkelvoudig decoderen rond Rx, periode-middeling en automatisch wissen van het gemiddelde voor Q65, a-priori-analyse, deep search en aggressief niveau voor JT65, F Tol voor JT65, JT9, MSK144 en Q65. De meest gebruikte zijn ook knoppen naast de modus: “Avg” en “Auto ⟲” in Q65, “AP” en “Deep” in JT65. Ze gelden vanaf de volgende periode.",
  "t.9g4dn70ez6": "Test op een kunstantenne: roep CQ en let op de radio.",
  "t.9kg79qblm9": "Aurora werkt ook als de radio niet via CAT is verbonden: het decodeert en zendt gewoon, maar je wijzigt de radiofrequentie zelf.",
  "t.9noy5epnzd": "Alternatief: type JT_MESSAGE op de poort van de primaire server, als je ook de status in Log4OM wilt (frequentie, huidige DX). Slechts één van de twee, niet allebei.",
  "t.9pbtgwzcrg": "Meestal hoef je [[ctl.hound]] niet aan te raken: met [[gen2.houndAuto]] aan (standaard) schakelt Aurora Hound in, zodra je de Fox kiest en hoort zenden in Fox/Hound (regels met het label FOX), zet Tx boven 1000 Hz en schakelt [[ctl.split]] in; het schakelt vanzelf uit als het station met normale berichten antwoordt of je een andere DX kiest. De knop [[ctl.hound]] is alleen om het met de hand af te dwingen.",
  "t.9qxdctd8wa": "Modes FST4 en FST4W (baken)",
  "t.9qzmjcgx19": "[[ctl.enable_tx]] en STOP zijn altijd binnen handbereik.",
  "t.a3krvubt7f": "Onder Linux gebruikt Aurora PulseAudio of PipeWire en toont dezelfde apparaten als WSJT-X en JS8Call: kies voor ontvangen de ingang (“alsa_input…”), voor zenden de uitgang (“alsa_output…”). De naam die je in WSJT-X gebruikt kun je ook met de hand intypen.",
  "t.a76c6sw8s3": "De coderegels zijn verborgen; om ze te zien schakel je [[gen2.showOtp]] in in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]].",
  "t.abp15bzhz6": "Als een sterk station begint of ophoudt, verandert de AGC van de radio het volume en gaan zwakke signalen op dat moment verloren. [[ctl.agc]] brengt die stukken terug op het juiste niveau. Laat het aan staan.",
  "t.aias45wioh": "De stijl van het radiodisplay kiezen.",
  "t.aipr6sy3pn": "Icom IC-7300, IC-705, IC-9700: één USB-COM-poort (CI-V loopt over de USB-kabel) plus de geluidskaart “USB Audio CODEC”. Kies bij [[cat.rig]] het model met de naam van de radio; de snelheid en het CI-V-adres ([[cat.civ]]) moeten gelijk zijn aan die in het radiomenu (optie CI-V, zie de handleiding).",
  "t.aoaohszh2x": "[[nav.settings]] › [[sw.sec.access]] › [[tab.support]]: “[[bak.make]]” zet het bestand Aurora-impostazioni-….zip op het Bureaublad.",
  "t.aw03ud6q49": "Open [[nav.settings]]: links staat de boom met instellingen, verdeeld in gekleurde families: “[[sw.sec.station]]”, “[[sw.fam.modes]]”, “[[sw.fam.log]]”, “[[sw.sec.look]]” en “[[sw.sec.access]]”. Bij het openen is alles dichtgeklapt: een klik op een familie klapt die open, en binnen “[[sw.fam.modes]]” heeft elke modus een eigen tak met eigen pagina’s.",
  "t.b7vrihwz6k": "Voer je roepnaam en je locator in (6 tekens, bijv. FN42ab).",
  "t.b99hj6sb6r": "Verplaatsbare rasters, modus van de spots uit het bandplan, QSL-route van DXpedities",
  "t.baxob1wmt3": "Roepnaam en locator: het eerste wat je invoert.",
  "t.bbpzoqugz": "Open op de pc [[nav.settings]] › [[sw.sec.access]] › [[sw.tab.phone]] en druk op “[[acc.pair]]”.",
  "t.bdai6gj52h": "Tune start nu meteen, ook halverwege een lange periode. Voor JT65 is er de knop ⟲ «Clear Avg» die het gemiddelde op nul zet. In de DX-cluster, waar één klik genoeg is, staat dat ook in de hint. Is de PTT-poort bezet, dan meldt het bericht welk programma hem vasthoudt, en WSPRnet toont hoeveel uploads er nog wachten. Tx Pct stuurt geen 0 meer als je het leegmaakt, LoTW verschijnt in het roepnaamvak alleen als het station het gebruikt, en de rotor is kleiner.",
  "t.bgxfn1t9w1": "Welke computer je nodig hebt",
  "t.bh2uzibmbp": "Satellietkaart inbegrepen en Aurora beter op Linux",
  "t.bicbv2se9o": "[[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]: kies het model, daarna “[[cat.preset.apply]]” en [[cat.connect]].",
  "t.bn8ldujd3y": "Zet op dezelfde pagina, bij “[[rx.grp]]”, aan wat je in het uitgebreide display wilt zien: tweede VFO, meters, PRE en ATT, AGC, NB/NR/notch, versterkingen, RIT/XIT, ATU, gebruikte VFO.",
  "t.bqdobcl2dx": "De berichtenlijst",
  "t.bt13cugmym": "Het tandwiel ⚙ op elke modipagina (FT8, PSK · RTTY · CW, SSTV, Satellieten, Contest…) opent Instellingen meteen op de tak van die modus.",
  "t.bx2rzprip8": "In Bandactiviteit heeft de rij die alleen nieuw is omdat ze onbevestigd is een lichtere, gestreepte kleur, anders dan een echte nieuwigheid. Ook wordt het Tx-veld rood en verschijnt er bij het begin van de zending een waarschuwing als het uitgezonden signaal buiten 200-2700 Hz valt: veel radio’s knijpen daar het vermogen af. De zending wordt niet geblokkeerd.",
  "t.c1brvz8d3h": "Bij de eerste start vraagt een stapsgewijze gids om taal, roepnaam en locator, geluidskaart en radio; elke stap kan worden overgeslagen en alles kan later worden gewijzigd in [[nav.settings]].",
  "t.c2ymqxc0sf": "Logboek op dezelfde pc: 127.0.0.1. Logboek op een andere computer: het IP-adres daarvan.",
  "t.cif26b4j8h": "Log4OM: Settings → Program Configuration → Software Integration → Connections. (indicatieve naam, controleer je programmaversie)",
  "t.ck0cv0mfjh": "Installatieprogramma met logboek en rapporten",
  "t.ckzmphktho": "Het menu «Modus» van de pagina PSK · RTTY · SSTV bevat nu CW: je zendt met een audiotoon met afgeronde flanken, met snelheid in WPM en macrocommando’s zoals <WPM:n>. Bij ontvangst volgt een decoder met adaptieve drempel de snelheid van het signaal, ook met ruis en squelch. CW-frequenties staan in de bandkeuze.",
  "t.cmckknb386": "SDR met TCI (ExpertSDR, Thetis)",
  "t.cra1tccxuh": "De eerste keer leest het vak de pagina’s in en duurt het anderhalve seconde; daarna is zoeken direct. Ook paginanamen worden doorzocht.",
  "t.cwz5zkuxn2": "Fox-expedities zenden af en toe een code (bijv. K8R.920749). Aurora laat die controleren en zegt je of de Fox de echte is.",
  "t.d2janvl824": "DX Cluster: tabel met rasterlijnen, kolommen die je verplaatst door de kop te slepen en verbreedt door de rand te slepen; rechtsklik → «Kolommen herstellen». Klok: bij het opstarten wacht de synchronisatie op het netwerk en, zolang de tijd afwijkt, wordt elke minuut gecontroleerd, zodat de waarschuwing vanzelf verdwijnt. Met Instellingen open kunnen de meldingen weer worden gesloten; het vak met de roepnaam (QRZ.com/HamQTH) is leesbaar boven de lijsten. Tijdens het zenden blijven modus en frequentie vergrendeld zonder van kleur te veranderen. De dubbele «Wissen» en «Spot DX» zijn uit de opdrachtbalken verwijderd; «Auto» staat aan het eind van Stop en Decoderen.",
  "t.d2tnhs6ahg": "In PSK31 en PSK63 worden onzekere tekens niet afgedrukt en dalen de fouten (PSK31 van 17% naar 14%, fldigi 20%); ruis levert geen verzonnen tekst meer op. Het paneel «Signalen» leest alle PSK-signalen van de browser tegelijk, met gecontroleerde roepletters, en een filter tegen knetterstoringen halveert de fouten in PSK31 (van 28% naar 13%).",
  "t.d2x3zryxqi": "Zet in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]], vak “[[cat.share]]”, “[[cat.share.on]]” aan (poort 4532): het wordt vanzelf opgeslagen. Het te gebruiken adres verschijnt daar zodra de radio is verbonden.",
  "t.d4jxky1ak1": "Elk gedecodeerd bericht verschijnt met zijn frequentie; “QSO” brengt de radio naar dat signaal in Q65 met de juiste periode en submodus. Voor EME toont de Maan-regel azimut, elevatie en Doppler, en de kolom Sked de te gebruiken frequentie.",
  "t.d61pm7e56g": "Blokkade door een ander programma: met “Accept UDP requests” aan kan een verbonden programma het zenden voor beperkte tijd blokkeren; het Tx-paneel zegt wie het blokkeert.",
  "t.d8g5lzsf9j": "Kies in [[nav.settings]] › [[sw.sec.look]] › [[sw.pg.alerts]] een geluid voor elke gebeurtenis.",
  "t.dg9hfpm8v0": "Druk op “[[rot.short]]” om naar het DX-station te draaien, “[[rot.long]]” voor de lange weg, de stappen −10°/−2°/+2°/+10° om bij te stellen, of klik op de roos of typ de graden en druk op “[[rot.go]]”. “[[rot.stop]]” stopt de rotor meteen.",
  "t.dgygycjm1e": "[[auto.b4]]: stations, landen gekozen uit de DXCC-lijst en, als je wilt, alleen bepaalde continenten. De filters van [[panel.all]] (Instellingen › Modi › FT8 · FT4 › Berichten en filters) tellen ook mee: wie ze verbergen krijgt nooit een automatisch antwoord, ook niet in dry run, en het logboek zegt dat.",
  "t.djnnij0ykf": "Druk bovenaan de pagina op [[wfs.preview.show]]: de echte waterval en het echte spectrum blijven in beeld terwijl je de opties wijzigt, en elke wijziging is meteen zichtbaar. Het voorbeeld gaat uit als je de pagina verlaat.",
  "t.dokxt6ihvx": "De baken zendt op de Tx-frequentie als die tussen 1400 en 1600 Hz ligt, anders op 1500 Hz. Met een samengestelde roepnaam, of met een locator van 6 tekens en [[mode.wsprType1]] uit, wisselt hij af met “<CALL> LOCATOR6” (in FST4W zonder het vermogen). Bij luisteren decodeert FST4W in de subband 1400-1600 Hz, zoals WSJT-X. Met split “[[cat.split.rig]]” of “[[cat.split.emulate]]” (WSPR, FST4W, FST4) volgt de toon de verschuiving van de radio en komt hij niet naast de frequentie uit.",
  "t.dp4y67n7qx": "Snelheid: [[cat.baud]] moet gelijk zijn aan die in het CAT-menu van de radio (in het radiomenu, zie de handleiding: de optie CAT RATE of CI-V…). Als ze verschillen, antwoordt de radio niet.",
  "t.du7mf6xmb7": "[[nav.settings]] › [[sw.fam.log]] › [[tab.cluster]]: “[[cluster.enabled]]” aan en een server gekozen.",
  "t.e3hmq7adpo": "Voer in het vak “Modo UDP” IP 127.0.0.1 en poort 2237 in op de rijen “Msg ID 5” en “Msg ID 12” (de rij “Msg ID ADIF” is niet nodig), en dan “Chiudi” (Sluiten).",
  "t.ecx9x8bei5": "Open [[nav.fox]] in het bovenmenu en druk op “[[fox.off]]”: je zendt in even periodes, onder 1000 Hz.",
  "t.eiapucegxa": "Bandactiviteit toont de hele band (met de knop “Filter” kies je slechts enkele soorten oproepen); het RX-venster toont jouw RX-frequentie (±50 Hz) en de berichten aan jou gericht. Beide zijn aanpasbaar.",
  "t.exauphqtlq": "De knop “[[ctl.spot]]” staat in het tabblad DX Cluster van de pagina Station (FT8 en de andere modi): hij opent het spotvenster met de DX van de QSO, de radiofrequentie en de modus. De spot die je verzendt verschijnt meteen in de lijst onder je roepnaam.",
  "t.ey73gwvooc": "De radio zendt niet",
  "t.f2y8dsur61": "OmniRig wordt nu rechtstreeks via COM aangestuurd, zoals WSJT-X doet: geen PowerShell meer, dus geen «toegang geweigerd», geen OmniRig-venster dat steeds weer opduikt en snellere PTT. Met native Cat4OM (Instellingen › CAT › «Cat4OM (insieme a Log4OM)») bedienen Aurora en Log4OM tegelijk dezelfde radio. Rig en Fake It split werken nu ook met OmniRig en kunnen in Instellingen met TCI worden gekozen. De Tx-vertraging is instelbaar in Instellingen › Algemeen, van 0 tot 0,5 s (standaard 0,2 s).",
  "t.f2yqc4ngx7": "PTT schakelt 200 ms vóór de audio in en 200 ms erna uit, zoals in WSJT-X. Zendingen langer dan 15 seconden (JT65, JT9, JT4, Q65 vanaf 30 s) worden niet meer geweigerd. Entiteiten die alleen in WAE bestaan zijn in cty.dat geen DXCC-landen meer en de achtervoegsels /R, /Q, /FD, /FF, /LT, /LGT behouden het eigen land van de roepnaam. PSK Reporter meldt dezelfde roepnaam hooguit elke 5 minuten. Wavelog accepteert API v2-tokens. Wait and Call met «Skip Tx1» stopt na 6,2 perioden en Wait and Pounce wordt ontwapend als je zelf de DX kiest. GridTracker en JTAlert: «alleen automatisch» laat het bericht afmaken en «Clear» stuurt de Clear. Als de audio-uitgang halverwege verloren gaat, is het resultaat een fout. FT8 decodeert meer zwakke signalen en EU VHF-contestberichten; het ADIF-logboek schrijft PSK en FST4 als hoofdmodus met SUBMODE.",
  "t.f5l3jf3u6p": "[[ctl.hold_tx]] houdt je Tx vast: bij het beantwoorden verschuift alleen Rx.",
  "t.f9iaul69kt": "Het totaal aantal QSO’s staat in de balk van het paneel; om het hele logboek te zien en als ADIF te exporteren gebruik je [[nav.log]] in het bovenmenu.",
  "t.fc5unsp08w": "Stappen in Aurora, van de frequentie tot de gelogde QSO.",
  "t.fci05adtwr": "Maak in Cat4OM de groep aan met je radio en controleer of die verbonden is. Log4OM en Aurora gebruiken beide die groep.",
  "t.feipt5eqk5": "Als de Fox niet antwoordt, blijft Aurora roepen. Na de eerste R+rapport zonder RR73 verschuiven latere pogingen 300 Hz ten opzichte van de Fox-frequentie.",
  "t.fi2irto0le": "Met het vakje «Gemiste QSO’s opnieuw sturen» (Instellingen › Log › Integraties) blijven de QSO’s in een wachtrij staan als het logprogramma op de pc gesloten is, ook na een herstart, en worden ze vanzelf verstuurd zodra het log weer opengaat, in de juiste volgorde en maar één keer. Na zeven dagen in de wachtrij worden ze verworpen.",
  "t.fki0flzr4y": "Op de Contest-pagina: F1 start Auto CQ (de contest-CQ elke periode), F2 uitwisseling, F3 R + uitwisseling, F4 afsluiting; Esc stopt het zenden meteen, dubbel Esc wist ook het huidige QSO. Boven de decodes: de frequentie (alleen contestbanden) en het vak RX/TX (klik op TX om te stoppen, klik op RX om het QSO te wissen). “Hoe werkt het” vat de regels samen en wat er wordt verzonden. Alleen QSO’s die tijdens de wedstrijd vanaf deze pagina zijn gestart komen in het contestlogboek.",
  "t.folw8r9el2": "Controleer of [[ctl.monitor]] aan staat.",
  "t.fr5hkkschj": "In [[nav.settings]] › [[sw.sec.station]] › [[sw.pg.sdr]] stelt de knop “[[sdr.useAll]]” CAT en audio in één keer in. S-meter, vermogen en SWR komen van de SDR; PWR − / + van het display wijzigen het SDR-vermogen en TUNE schakelt de tune-draaggolf aan en uit. Elk commando wacht tot de SDR het bevestigt: gebeurt dat niet, dan meldt Aurora het. “Power on” en “Power off” schakelen de SDR via TCI aan en uit.",
  "t.ft3y4nqdh4": "Waar de instellingen staan en hoe ze worden opgeslagen.",
  "t.fy02sxwno0": "Daaronder staan bandactiviteit, de DX Cluster van de band, laatste QSO’s, de zes Tx-berichten, waterval en CQ.",
  "t.g09cbf3nv7": "Bovenaan de cijfers van het logboek (QSO’s, landen, zones); eronder de QSO’s per band en de DXCC-kaart van het station dat je werkt. Ontbrekende landen openen met een klik; het vak “[[logio.title]]” staat al open, met [[logio.export]] en [[logio.import]].",
  "t.g1d92z0iow": "Hard geseinde CW-stations laten bij elke flank een horizontale lijn op de waterval achter (klikken). “[[digi.mi.anticlick]]” in het menu [[digi.menu.view]], standaard aan, haalt ze weg zolang de pagina luistert: breedbandige energie die korter dan 10 ms duurt wordt gedempt voordat de regel wordt getekend, de signalen blijven. Zolang deze pagina luistert geldt dit ook voor de waterval van de andere pagina’s.",
  "t.g6z5e46cpn": "Stations in de wachtrij zetten die je roepen terwijl je in een QSO zit.",
  "t.g7ocqb0ygi": "Kies in FT991Link de poort van de radio en druk op “COM Port” om hem te openen.",
  "t.g9l15etnfs": "De wachtrij en [[ctl.answer_all]]",
  "t.gfiwgibl0p": "Tx-vertraging: in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], vak [[gen2.operation]], is [[gen2.txDelay]] de tijd tussen PTT aan en het begin van de audio, 0 tot 0,5 s (standaard 0,2 s, zoals “Tx delay” in WSJT-X). Verhoog hem als de radio of CAT traag is en het begin van het bericht verloren gaat.",
  "t.gkwllsuexv": "Zegt Aurora dat rigctld (het Hamlib-programma) ontbreekt? Meestal heeft de antivirus het verwijderd. Onder Windows: 1) open [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]; 2) druk op “[[cat.restore]]”: Aurora downloadt het opnieuw van de officiële Hamlib-release en controleert de checksum; 3) druk op [[cat.connect]]. Verdwijnt het weer, voeg dan de Aurora-map toe aan de uitzonderingen van de antivirus.",
  "t.glth09yywf": "Een klik op een resultaat (of Enter voor het eerste) opent de juiste pagina en brengt de optie in beeld, even oplichtend.",
  "t.gsf69m2sgs": "De brede DXpeditie-modus, compatibel met WSJT-X SuperFox. In test.",
  "t.h111i6llgy": "De radio instellen",
  "t.hg8je5qhsk": "FT-991/FT-991A met FT-991(A) Link",
  "t.hgskhaihf4": "Tijdens het zenden (ook van een macro) worden de al verzonden tekens rood, met een streepje op het bereikte punt, en in het ontvangstvenster verschijnt de echo in het tempo van de uitzending.",
  "t.hstr2um28j": "CW: zenden en decoderen op dezelfde pagina",
  "t.i2f1r39jrg": "De laatste QSO’s in één oogopslag en de ADIF-export.",
  "t.i6a22fg6dk": "USB-stuurprogramma: open Apparaatbeheer van Windows en kijk onder “Poorten (COM en LPT)”: de poort van de radio moet daar staan, met de radio aan en de kabel aangesloten. Ontbreekt hij, of heeft hij een geel uitroepteken, dan ontbreekt het USB-stuurprogramma: installeer dat van de fabrikant (voor veel Yaesu-radio's is dat het Silicon Labs CP210x-stuurprogramma).",
  "t.i6hhzs4qvt": "Na elk beeld wordt je roepletters in FSK-ID uitgezonden, ook leesbaar voor MMSSTV (uit te zetten in Instellingen); bij ontvangst wordt het gelezen en in het log gezet. Ook als de VIS gemist is, wordt de mode herkend aan het ritme van de regels; het spectrum toont afstemmarkeringen en het binnenkomende beeld heeft ruisonderdrukking.",
  "t.i8mhlawjed": "Als het signaal buiten het audiobereik van 200-2700 Hz komt, verminderen veel radio’s daar het vermogen.",
  "t.ihlpswr36n": "Pop-upmeldingen",
  "t.il6pe9mko5": "In het filter van Bandactiviteit tonen de knoppen “[[kind.new_state]]” en “[[kind.new_state_band]]” Amerikaanse stations uit een staat die nog nooit of nog niet op deze band is gewerkt. De staat komt van QRZ.com of HamQTH (roepnaamopzoeking aan), de gewerkte staten uit het Log4OM-logboek. Dezelfde twee keuzes staan ook in Automatisering: Auto antwoordt op CQ’s uit een nieuwe staat.",
  "t.itwpwec46x": "CW/PSK/RTTY decodeerde niet bij de eerste keer openen, Fox-rijen, Nederlandse installer",
  "t.iw2zdrzz5u": "Als de DXpeditie niet zegt Fox/Hound te gebruiken, roep haar dan als een gewoon station, zonder [[ctl.hound]].",
  "t.ix83n1ftf8": "Contest: toetsenbord en commando’s",
  "t.jlzjxdm1u3": "Kies, nog steeds in “Fast QSO”, in het menu onder “Auto-Save” “UDP 12” (dat krijgt alle QSO-gegevens) en vink “Auto-Save” aan als je wilt dat het QSO aan het eind vanzelf wordt gelogd.",
  "t.jnbws1wb1i": "Decoderopties van WSJT-X",
  "t.js771xsd16": "Twee programma's die tegelijk de radio besturen storen elkaar. Beter is dat alleen Aurora met de radio praat en de andere programma's Aurora vragen.",
  "t.jsguk5ilg7": "Open [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]].",
  "t.jz1muqdbh4": "“[[acc.open]]”: geen code voor wie op het thuisnetwerk zit. Het staat standaard aan, dus thuis is geen code nodig; via internet is de code altijd vereist. Dit wijzig je alleen vanaf de pc. Een pagina van een andere website die in de browser op dezelfde pc openstaat, kan de status (roepnaam, locator, log) niet lezen en de radio niet laten zenden.",
  "t.k027ipmga7": "Kies de [[fox.slots]] (tot 5 stations in dezelfde zending) en voor wie de CQ is.",
  "t.kbiuvbcx2e": "Elke rij is een gedecodeerd bericht: tijd, rapport, tekst, land met vlag en afstand. De labels rechts geven aan wat er bijzonder aan is.",
  "t.kezkywakhh": "Schrijf in [[gen2.bandHopList]] de items gescheiden door komma’s: «FT8 20m», «FT4 40m» of een frequentie in kHz zoals «14090».",
  "t.khtearoamd": "Radio delen met Log4OM via Cat4OM",
  "t.kjki0dxvs4": "Rood label: dat station roept jou.",
  "t.kmxlgvb2wl": "[[nav.stats]]",
  "t.knqavm0mr8": "Het paneel toont spots voor de gebruikte band: op een stille band kan het leeg blijven. Probeer een andere server.",
  "t.kq89c29o3a": "Het logboek sturen naar wie je helpt",
  "t.ku7gfu5kxq": "[[bak.note]]",
  "t.kut2fdg4rz": "Modus JT4",
  "t.l04og0i7fm": "Dubbelklik op de CQ-rij: het antwoord start meteen, daarna gaat [[ctl.enable_tx]] aan en een melding zegt “Answering …”. Aurora zendt in de juiste periode. Als je al zendt en het nieuwe station in dezelfde periode moet worden geroepen, stopt de zending niet: het bericht wisselt direct om.",
  "t.l2bm1ohmkn": "Een optie vinden in Instellingen",
  "t.l5a66cqtcd": "Een station in de lijst heeft logboeken geüpload, maar dat betekent niet dat het jouw QSO zal bevestigen: de balk is slechts een hint.",
  "t.l7n1vo4azh": "Logboek op een andere pc: de Windows-firewall van die pc moet UDP op de gekozen poort doorlaten.",
  "t.la4o0nopgh": "Open altijd eerst Aurora en daarna de andere programma's.",
  "t.ljp664ufso": "Frequentielijst",
  "t.lnzas6uggy": "Paars label: dat station heeft op jouw oproep geantwoord.",
  "t.lofyx0j9l8": "MSK144 is voor meteorscatter-verbindingen op 6 m en 2 m: T/R-periodes van 5, 10, 15 of 30 s (standaard 15 s), berichten in FT8-stijl, een frame van 72 ms dat de hele periode wordt herhaald, zodat één meteoorping genoeg is om het te ontvangen. Aurora zendt altijd op 1500 Hz (tonen op 1000 en 2000 Hz). De frequenties hangen af van de regio: 50,260 MHz (regio 2 en 3) of 50,380 MHz (regio 1), 144,150 of 144,360 MHz.",
  "t.lt1g4snzrv": "Test: druk op “[[sw.testCat]]”: er moet staan dat CAT verbonden is. Daarna “[[sw.testPtt]]”: de radio zendt een seconde, gebruik dus een kunstantenne of een geschikte antenne.",
  "t.lz8o4djfla": "Als de zender na het beeld zijn roepnaam in FSK stuurt (FSK ID, zoals MMSSTV), leest Aurora die, toont die boven het beeld en schrijft die in de geschiedenis en in het veld “[[sstv.log.call]]” van “[[sstv.log.title]]”. Met een roepnaam in het log zoekt Aurora het station meteen op met de ingestelde opzoekdienst (QRZ.com of HamQTH) en vult lege velden voor naam, QTH en locator in; het land komt uit cty.dat. Jouw uitzendingen eindigen met jouw roepnaam in FSK: uit te zetten in [[sw.sec.sstv]] › “[[sstv.set.fskId]]”.",
  "t.m30ab28chi": "De radio bedienen vanaf het display",
  "t.maf11lah0w": "LogHX (gratis logprogramma van RX4HX, rx4hx.qrz.ru, versie 3.1) ontvangt Aurora zoals het WSJT-X, JTDX en MSHV ontvangt: QSO’s worden vanzelf gelogd en het venster “Active calls for FT8” toont de gedecodeerde stations. Je hebt een bestemming in Aurora nodig en de instelling van het digitale programma in LogHX, met dezelfde poort.",
  "t.md469p3nwa": "Gekoppelde programma’s en logboeken",
  "t.ms98humib0": "Controleer de klok: als de tijd niet klopt verschijnt bovenaan een gele waarschuwing.",
  "t.mt7ueuomnb": "Uploaden naar WSPRnet: zet in [[nav.settings]] › [[sw.fam.log]] › [[tab.online]] [[ens.k.WSPRnetUpload]] aan en sla op. Na elke WSPR- of FST4W-periode stuurt Aurora binnen 20 s na het decoderen de ontvangen signalen (of, als er geen zijn, de status van uw station) naar wsprnet.org.",
  "t.mvyoyinfs4": "Stel je locator in bij Instellingen (Algemeen) en druk op “[[sat.tle.refresh]]”: Aurora downloadt de baangegevens van CelesTrak (die worden elke dag vernieuwd).",
  "t.mydz7a6b1f": "Controles als de waterval signalen toont maar de lijst leeg blijft.",
  "t.mzw20jxh0r": "[[bak.title]]",
  "t.n0te1iliz3": "RTTY: ontvanger, squelch en RTTY-instellingen",
  "t.n0yhuwvn4l": "Kies bij “[[rd.layout]]” hoe het display en het uitgebreide display rechtsboven staan: [[rd.layout.single]], één scherm met een grote VFO A links en VFO B met de indicatoren rechts, of [[rd.layout.pair]].",
  "t.niq3ak0vdy": "[[auto.b3]]: pogingen en pauze per station, hoogstens zoveel QSO’s per uur (0 = geen limiet) en, als je wilt, een tijdvenster in lokale tijd: daarbuiten wacht de automatisering.",
  "t.nqnhn7ihgv": "PSK, RTTY en CW: open uitzending en live typen",
  "t.nvlesdka3p": "Voor wie een DXpeditie bedient: de klassieke Fox-modus, in test. Geen SuperFox.",
  "t.o5q8pcv1eb": "[[cat.backend]]: kies Hamlib. Met Hamlib krijg je ook de echte S-meter, het vermogen, de SWR en de ALC van de radio.",
  "t.o6jgv7ztqw": "PSK en RTTY: pagina en weergaveopties",
  "t.o7la0shcta": "Gevoeliger FT8-decoderen",
  "t.o7u6dgxoz1": "Aurora leest de opmerking: “UP 5”, “UP5”, “5 UP”, “5UP”, “10up”, “DN 2” of “DOWN 2” (eronder), “QSX 14.030” of “QSX 030” (waar ze luisteren). “UP” alleen betekent 1 kHz; “UP 1-3” betekent het midden, 2 kHz. Getallen in kHz, hoofdletters of kleine letters. In de spotregel staat een label “UP 5”: erboven zweven geeft aan waar het zenden heen gaat. “UP 14.0305”, “QSX 21.2” en frequentiebereiken worden goed gelezen, en een locator zoals “DN31” wordt niet voor “DN” aangezien.",
  "t.ogq8ylljk0": "QMAP: elke Q65 in een stuk van de band",
  "t.ogxbunrapx": "Aurora downloadt elke dag de openbare lijst van de ARRL met LoTW-gebruikers (lukt dat niet, dan blijft de oude staan). Zweef over de roepnaam: “Gebruikt LoTW: laatste upload” verschijnt met de datum. In het roepnaamvak verschijnt “LoTW” alleen als het station het gebruikt, in groen en zonder datum; gebruikt het dat niet, dan verschijnt er niets. Dit geldt ook voor stations uit de DX-cluster, gecontroleerd aan de openbare lijst van de ARRL.",
  "t.pe7p3yu2xx": "Nieuwe pagina «Satellieten» (aangevraagd door UN7MBV voor RS-44): wereldkaart met dag en nacht, hemelradar, gegevens van de gekozen satelliet en een lijst met doorgangen, met CelesTrak-banen die zichzelf verversen. Met Hamlib volgt de radio elke seconde de Doppler, ook bij inverterende lineaire transponders (ISS, RS-44, SO-50, FO-29, AO-7, CAS-4A/B), en de rotor volgt de satelliet in azimut en elevatie.",
  "t.pfvdroh0z0": "Elk CQ-vakje toont vlag, roepnaam en land; bericht, rapport en tijd verschijnen als je er met de muis boven houdt. Dubbelklikken antwoordt, rechtsklikken zet in de wachtrij. Een station dat 15 minuten niet is gehoord verdwijnt vanzelf.",
  "t.pgszkmlci1": "Zet de radio op de door de expeditie aangekondigde frequentie, in FT8.",
  "t.ppry2pp0z0": "[[cat.catmode]]: kies USB data (DATA-USB) voor FT8. De audio loopt zoals gewoonlijk via de USB-geluidskaart van de radio.",
  "t.psz1ghp9ed": "Het Tx-veld van het bedieningspaneel wordt rood als de Tx-frequentie buiten 200-2700 Hz ligt.",
  "t.q5mp93x9kl": "Zoek en kies met “[[rot.set.launch]]” het “[[rot.set.model]]”, daarna de “[[rot.set.port]]” en “[[rot.set.baud]]” van de rotorinterface; druk op “[[rot.set.apply]]”.",
  "t.q65igl199t": "De knop [[ctl.jt_both]] verschijnt alleen als de modus JT65 of JT9 is: als hij aan staat, decodeert hij ook de andere JT-modus in dezelfde minuut. Je zendt in de gekozen modus.",
  "t.q8nlqs5kai": "In FT8 blijft het vermogen de hele zending constant: dat is normaal.",
  "t.q8yimdbdjy": "[[ctl.agc]]: zwakke signalen naast sterke stations",
  "t.qacpy2631i": "Onzekere tekens verschijnen duidelijk gemarkeerd en de squelch verzint geen tekst meer op ruis; op witte ruis is Aurora gelijk aan of beter dan fldigi en MMTTY. Het nieuwe venster «RTTY-instellingen» (klik onderaan op de mode) bundelt Rev, AFC, Snap, Squelch, Shift, Baud en tekensets in vier profielen.",
  "t.qcxu5862tg": "PSK: meer waarschijnlijkheid, alle signalen en minder knetters",
  "t.qdbeun6jt3": "[[wfs.specPct]] (fabriek 30) toont het spectrum onder de waterval; kies in [[wfs.specMode]] [[wfs.current]] of [[wfs.cumulative]] (het gemiddelde van de periode).",
  "t.qeq0dohwtr": "Verlaag Pwr tot de ALC op of bijna op nul staat. Kies het vermogen met de knop van de radio, niet met Pwr.",
  "t.qfgp9s0wmg": "De pagina “PSK · RTTY · SSTV” past op één scherm: bovenaan macroblokken (rechtsklik om te bewerken) met daarnaast de keuze van IARU-band en frequentie; eronder ontvangen en zenden (de scheidingslijn ertussen is versleepbaar), rechts de tabbladen DX Cluster en Logboek met het huidige QSO, en onderaan de waterval. De modus (PSK31, PSK63, RTTY, SSTV) wijzig je in het menu “Modus”. Het menu “Weergave” schakelt in: onderstreepte verzonden tekst, alleen hoofdletters, doorgestreepte nul, knipperende TX, haarlijnen op de waterval en standaard 599-rapporten. Met split (Lock) is het rode paar op de waterval de zending: een klik verplaatst het, met Ctrl verplaatst in plaats daarvan het ontvangen. In de DX Cluster stemt een klik op een spot het signaal af op de ontvangsttoon en verplaatst, met “up N” in de opmerking, de zending; de knop “Spot DX” stuurt de spot naar DXSummit.",
  "t.qngj247kdf": "[[wfs.barsOn]] toont de Rx- en Tx-balken; [[wfs.freqOn]] de frequentie waar je met de muis naar wijst. [[set.reset]] zet alles terug op de fabriekswaarden.",
  "t.qqg4qcfz6z": "Om twee naburige vensters van dezelfde hoogte te verwisselen sleep je de titelbalk naar links of rechts: het venster volgt de muis en het andere schuift over.",
  "t.qzbls7dalr": "Druk op [[cat.connect]]: de status moet “Verbonden” worden, met groep, radio en rol (bijvoorbeeld group-1/kenwood/ts-990 — slave). Log4OM houdt de controle over de radio; Aurora schrijft (frequentie, modus, PTT, split) alleen als het nodig is en volgt de QSY’s van Log4OM, bijvoorbeeld bij een klik op een spot.",
  "t.r377i7cy3a": "De split gaat uit met “[[cluster.splitDx.off]]”, bij het wisselen van band of frequentie, bij een klik op een spot zonder UP en bij terugkeer naar FT8 of FT4. Lukt het uitzetten niet, dan meldt Aurora niet dat het uit is terwijl de radio nog in split staat; “[[cluster.splitDx.off]]” werkt niet tijdens het zenden.",
  "t.ra32xq0h78": "Wait and Reply: als je een DX hebt geroepen en [[ctl.enable_tx]] hebt uitgeschakeld, wordt de QSO vanzelf hervat wanneer de DX jou roept.",
  "t.rad6fz68vs": "Logprogramma’s koppelen (UDP)",
  "t.rbyx53gsup": "Voer UDP-poort 2237 in (adres 127.0.0.1) en laat multicast uit. Laat LogHX JTDX of WSJT-X niet starten: het digitale programma is Aurora.",
  "t.rg32monv8v": "FlexRadio, SunSDR, ExpertSDR: geen COM-poort, gebruik TCI ([[cat.backend]] → “[[cat.backend.tci]]”); bij FlexRadio werkt ook de SmartSDR CAT.",
  "t.ripejls4px": "De hoofdpagina met blokken",
  "t.s0kfl562hk": "Een station roept je terwijl je bezig bent: rechtsklik op zijn rij en hij komt in de wachtrij. In de lijst verschijnt een blauwe stip met zijn positie.",
  "t.schpi0xdk2": "[[nav.settings]] › [[sw.sec.station]] › [[tab.radio]]: druk op [[cat.connect]]; de status moet “Verbonden” zeggen met de frequentie van de radio.",
  "t.sdwvpcluri": "Roepnaamopzoeking (QRZ.com, HamQTH): [[nav.settings]] › [[sw.fam.log]] › [[tab.online]].",
  "t.si10133zlo": "Wait and Pounce: kies met [[ctl.enable_tx]] uit in [[gen2.pounce]] ([[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]]) welke CQ je wilt beantwoorden en schakel [[ctl.pounce]] in. Aan het einde van de periode beantwoordt Aurora de gekozen CQ vanzelf, waarbij reeds gewerkte stations worden overgeslagen.",
  "t.skqfgxjvvk": "Dezelfde contestinstellingen (activiteit, uitwisseling, categorie, Cabrillo-gegevens) staan ook in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[sw.sub.contest]], met de keuzelijst om de contest te kiezen; voor contests die MSK144 of Q65 toestaan staan ze in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.vhf]] › Contest. Het tandwiel ⚙ van de pagina [[nav.contest]] opent de tak van de modus die je gebruikt.",
  "t.st1vwkk4g6": "Tekst in PSK31, PSK63 en RTTY",
  "t.sxepdxiwbv": "Bediening",
  "t.szo7jtk9k4": "Het deel dat nog niet verzonden is, blijft bewerkbaar: klik erin en verbeter, wis of voeg toe; het al verzonden deel blijft ongewijzigd. Een macro die tijdens de uitzending start, sluit achteraan aan.",
  "t.t0hqszd6n3": "Het hart van UltraFOX is AQP-127 (Aurora Q-ary Polar), de polaire code van Aurora, implementatie door Tiziano Cassone IU3WJQ: 50 symbolen van 7 bits (47 voor het bericht en 3 voor controle) worden 127 tonen. Bij ontvangst weegt de decoder de kansen van de 128 tonen van elk symbool en corrigeert die welke door ruis en fading zijn verpest: hij decodeert tot ongeveer −16 dB in 2500 Hz, met tot 9 stations in één signaal.",
  "t.t3yynge1xt": "[[list.clear]] wist het berichtenvenster.",
  "t.tjgxbyits2": "Zegt Aurora dat de poort bezet is of de toegang geweigerd wordt, dan gebruikt een ander programma (of een ander exemplaar van Aurora) die COM-poort al: sluit het, of deel de radio zoals hierboven. Zegt het dat de poort niet bestaat of niet gevonden is, dan heeft Windows hem misschien een ander nummer gegeven: ververs de poorten, controleer of de radio aan staat en de kabel zit, en kies de COM-poort opnieuw. Onder Linux betekent “Permission denied” niet dat de poort bezet is: je hebt geen toestemming om de poort te gebruiken.",
  "t.tk3kme0bef": "Druk aan het eind op “[[contest.export]]”: Cabrillo 3.0, EDI of ADIF zoals de regels vragen, gecontroleerd vóór het verzenden, met de link naar de pagina van de organisator. Daarna zet “[[contest.end]]” alles terug naar de vorige instellingen.",
  "t.to46xwcz90": "Bijna alle verbindingsproblemen komen door een paar oorzaken. Controleer ze in deze volgorde voordat je elders zoekt.",
  "t.ton0b5zsq4": "RX/TX en Pauze openen de uitzending en houden die aan: de tekst gaat de ether in terwijl je typt en het nog niet verzonden deel kun je ook halverwege corrigeren, zelfs tijdens een macro. Verzonden tekens kleuren in het echte tempo van de audio en de echo bij ontvangst komt teken voor teken binnen.",
  "t.tp0fvwawlw": "De knop “Auto” in de bovenbalk schakelt het aan en uit zonder het menu te openen. De eerste keer vraagt hij, als het in dry run staat, of je naar de echte modus wilt overschakelen: met “Ja” start het meteen in de echte modus, daarna schakelt één klik het aan en uit.",
  "t.tqlhorkmi7": "Een station dat nooit de laatste 73 zendt: Aurora herhaalt RR73 hoogstens het aantal keren dat is ingesteld in [[nav.settings]] › [[sw.fam.modes]] › [[sw.sub.ft8]] › [[tab.sequence]], en stopt dan.",
  "t.tqzfvfjvyt": "Met [[ctl.enable_tx]] aan of tijdens het zenden hopt de rig niet: hij blijft waar je werkt.",
  "t.tsieh1ipmc": "Radio en audio",
  "t.tt94z7c9g2": "Voer onderaan, in het vak “Modo ADIF”, bij “Descrizione” (beschrijving) Aurora in en bij “Percorso file ADIF” (pad van het ADIF-bestand) C:\\Users\\<your user>\\AppData\\Roaming\\Aurora\\aurora_log.adi (of blader met het vergrootglas), en druk dan op de groene +.",
  "t.tv84vqu0gj": "Afstand en azimut verschijnen ook bij berichten zonder locator, als dat station die eerder heeft gezonden.",
  "t.tx073tffry": "De vensters hebben vaste afmetingen; alleen de volgorde en de breedte van naburige vensters veranderen.",
  "t.tyz9d8ka7k": "Het zenden meteen stoppen.",
  "t.ub3g29st9p": "Stations die je zoekt: voeg ze toe in [[nav.settings]] › [[sw.fam.log]] › [[tab.wishlist]].",
  "t.ujctmdn3xo": "S-meter en vermogen op het display",
  "t.uk7mnotwwu": "Daarna audio en radio: de onderdelen “De geluidskaart” en “De radio verbinden (CAT)” in de groep “Radio en audio”.",
  "t.uoyx6m6h4f": "Werkt met Hamlib, OmniRig, TCI en Cat4OM (als de radio split meldt); niet met FT-991(A) Link, dat alleen VFO A bestuurt. Zonder CAT stemt de spot alleen af. Is split niet mogelijk, dan gaat de radio toch naar de spot. Na een herverbinding van Hamlib wordt Split DX vanzelf opnieuw gezet; met Cat4OM gaat hij uit bij het afsluiten, ook na een herstart van Cat4OM.",
  "t.upzy42ggio": "De waterval en het spectrum hebben hun eigen instellingen, met fabriekswaarden. Wijzigingen zijn meteen zichtbaar en blijven na een herstart bewaard.",
  "t.uqengvwhnm": "Hoe de instellingen werken",
  "t.uqnpznr5kw": "CW: betere decodering en de hele band",
  "t.uylg1zjyvb": "Open in BBLogger “Configurazione interfaccia Wsjtx” (tandwielpictogram in “Fast QSO” of “Nuovo QSO”).",
  "t.vc90to0r5k": "Aurora draait op Windows; installeer het één keer en daarna werkt het zichzelf bij.",
  "t.vdajgwccuf": "SSTV: nieuwe pagina om beelden te ontvangen en te zenden",
  "t.vgea1q9fkz": "Scan en geheugens",
  "t.vu8wux1b1t": "De expeditie kondigt het aan op haar website: frequentie (meestal weg van de normale FT8-frequenties) en of ze klassiek Fox/Hound of SuperFox gebruikt.",
  "t.vw15nqasdm": "Zendbeveiligingen",
  "t.vxxsljkzfh": "“[[digi.mi.scanProps]]” in het menu [[digi.menu.options]] opent deze pagina meteen.",
  "t.w79q3skt6b": "“rotctld niet gevonden”: herstel Hamlib via [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] (rotctld staat naast rigctld).",
  "t.wavjdfmn1y": "Het rechtsklikmenu van de browser verschijnt niet meer: rechtsklikken is voor de wachtrij (kopiëren en plakken werken nog in tekstvelden).",
  "t.wbvl1kwrqa": "“[[acc.home]]” (aurora.local) blijft hetzelfde ook als de router het IP van de pc verandert: zet er een bladwijzer van op de telefoon.",
  "t.wd3md5j3gw": "“[[ens.g.udp]]”: [[ens.k.UDPServer]] 127.0.0.1, [[ens.k.UDPServerPort]] 2237. Het stuurt de WSJT-X-stroom (Heartbeat, Status, Decode, QSO Logged); met “[[ens.k.EnableUDP1adifSending]]” ook Logged ADIF. Bedoeld voor logboeken die naar “WSJT-X/JTDX” luisteren.",
  "t.wejbldv01b": "Druk op [[tx.cq]]. Wie antwoordt wordt automatisch afgehandeld.",
  "t.wewllajgwo": "[[nav.dxmap]]",
  "t.worcm09gkx": "De volgorde gaat vanzelf verder: rapport, R-rapport, RR73. Zodra je het rapport ontvangt, wordt de QSO gelogd.",
  "t.wtknyg9z8d": "Aurora stuurt QSO’s en status via UDP naar logboeken. Alles staat in [[nav.settings]] › [[sw.fam.log]] › [[sw.pg.reporting]].",
  "t.wufx184hm5": "Automatische antwoorden",
  "t.x3s17hxmzt": "De QSO-bediening zit in [[panel.tx]], onder de zes berichten, met de schuifregelaars Rx en Pwr op één rij. [[ctl.enable_tx]] en [[ctl.auto_tx]] zijn rood als ze aan staan: ze staan op het punt te zenden.",
  "t.x60rr2w9i3": "In het uitgebreide display zijn PRE, ATT, AGC, NB, NR, NOTCH, ATU, VFO, RIT en XIT knoppen: een klik wijzigt de instelling op de radio via CAT en de waarde wordt meteen teruggelezen.",
  "t.xa6p96oohb": "Icom: dezelfde snelheid als de radio (115200 aanbevolen) en in de radio bij CI-V USB Port “Unlink from [REMOTE]”.",
  "t.xcz3p79zjx": "Aurora controleert zelf op nieuwe versies en biedt ze aan. Het installatieprogramma sluit Aurora en start het opnieuw. Op een Mac vervangt Aurora zichzelf (Aurora.app) en start opnieuw: het moet in Programma's (of een eigen map) staan, niet geopend vanuit de .dmg; bij de eerste start na de update kan macOS om bevestiging vragen, omdat Aurora niet door Apple is ondertekend. Verbind na een update de programma's die de radio via Aurora gebruiken opnieuw. Wat er veranderd is, staat in [[nav.news]].",
  "t.xdjs7ci9eu": "Kleuren: groen in de lucht, blauw komende, grijs beëindigd, oranje als je het nu hoort. Hoeveel dagen de beëindigde bewaard blijven: “[[onl.dxpedDays]]”.",
  "t.xrm1jff9je": "Zet in Automatisering “[[auto.filterCallers]]” aan: ook bij een met de hand geroepen CQ antwoordt Aurora niet aan stations die door de filters van Bandactiviteit verborgen zijn (bijv. “niet mijn continent”) of in Automatisering uitgesloten zijn. “[[auto.contExcludeShort]]” naast de continenten sluit ze uit in plaats van alleen die te behouden.",
  "t.xt4ss10uip": "Klik op de waterval, CAT na herstart van de radio, lijsten en meldingen",
  "t.xu1254vyry": "Mode, band, taal, geluiden en thema met één klik.",
  "t.y0qhqtshdh": "Zend je en gaat de radio niet op zenden, dan verschijnt bovenaan een melding met de reden. Controleer in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] of de PTT-methode dezelfde is als in WSJT-X (CAT, of RTS/DTR op dezelfde poort) en probeer “Test PTT” onderaan de Instellingen. Aurora probeert de PTT ook als een uitlezing van de radio is gemist; antwoordt de radio niet, dan zegt de fout dat. Bij PTT via RTS/DTR geeft de melding, als een ander programma de poort vasthoudt, aan welk programma: sluit het en start Aurora opnieuw (de PTT-poort opent bij het opstarten, “Verbinden” is niet genoeg).",
  "t.y6wz3s9a56": "Een geluid voor elke gebeurtenis.",
  "t.y97lypgbu0": "Stem de radio met de hand af op dezelfde frequentie (die Aurora toont, bijvoorbeeld 7,074 MHz in FT8), in USB.",
  "t.ya32iqxk41": "Onder Linux verschijnen de poorten “/dev/ttyUSB*” en “/dev/ttyACM*” in de lijst en worden ook paden “/dev/serial/by-id/…” geaccepteerd, die bij een herstart niet veranderen. Wil je alleen PTT via RTS/DTR, zonder CAT, kies dan het Hamlib-model “Dummy” en geef de poort op.",
  "t.yqk7hehiia": "Open [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] en kies bij [[cat.backend]] “[[cat.backend.cat4om]]”.",
  "t.ysaoklqcur": "Zet “[[clock.atStart]]” aan: bij elke start corrigeert Aurora de tijd vanzelf. Om de pc-tijd te wijzigen moet Aurora als beheerder draaien.",
  "t.yvmtsq2ndm": "Typ in “[[fil.calls]]” de roepnamen die je wilt verbergen; in “[[fil.showOnly]]” de enige die je wilt zien. JA* komt overeen met elke roepnaam die met JA begint.",
  "t.z4627jxyco": "De QSO is kort: jij zendt roepnaam en locator, de Fox geeft je een rapport, jij antwoordt R+rapport, de Fox sluit af met RR73. Geen laatste 73 van jou.",
  "t.z86af14ogm": "De digitale handtekening (OTP-code) wordt ondersteund: als expeditie voer je de seed in op de pagina Fox en de code gaat mee in het signaal; als Hound controleert Aurora de Fox en de regel wordt “verified” of “invalid”.",
  "t.z8kqe79vg4": "Test: maak een QSO (ook op een kunstantenne) en controleer of de regel in het logboek verschijnt.",
  "t.zjfum6915o": "Juiste poort: kies in [[nav.settings]] › [[sw.sec.station]] › [[tab.radio]] de COM-poort van de radio bij [[cat.port]] (druk op “[[cat.ports.refresh]]” nadat je de radio hebt aangezet of de kabel hebt aangesloten).",
  "t.zkqdpjsksl": "FST4W-baken: kies naast de modus het vermogen (het echte bij de antenne) en [[mode.wsprPct]], en zet dan [[ctl.enable_tx]] aan. Aan het begin van de perioden die het percentage kiest, zendt Aurora “ROEPNAAM LOCATOR dBm”: net als WSJT-X beslist het met een willekeurige trekking per periode en, onder 40%, nooit twee perioden achter elkaar.",
  "t.ztdinm290o": "Het radiodisplay",
  "t.zuwxkjxgtd": "Instellingen als boom, met nieuwe pagina’s",
};
